1	import React, {
2	  useEffect,
3	  useCallback,
4	  useState,
5	  useMemo,
6	  useRef,
7	} from "react";
8	
9	import { useDSLStore } from "@/stores/dslStore";
10	import type { DSLFieldObject } from "@/types/dsl";
11	import type { EditorMode } from "@/types/dsl";
12	import type { RouteInput } from "@/lib/dslMutations";
13	
14	import styles from "./BuilderPage.module.css";
15	import DslEditorPage from "./DslEditorPage";
16	import { BuilderDeployConfirmModal, BuilderDeployToast, BuilderDragOverlay } from "./builderPageDeployOverlays";
17	import { VisualMode } from "./builderPageVisualShell";
18	import { BuilderGuideDrawer } from "./builderPageGuideDrawer";
19	import { BuilderImportModal } from "./builderPageImportModal";
20	import { BuilderNaturalLanguagePanel } from "./builderPageNaturalLanguagePanel";
21	import { BuilderOutputPanel } from "./builderPageOutputPanel";
22	import { useResizableWidth } from "./builderPageResizeHooks";
23	import { BuilderStatusBar } from "./builderPageStatusBar";
24	import { BuilderToolbar } from "./builderPageToolbar";
25	import { useReadonly } from "@/contexts/ReadonlyContext";
26	import { useAuth } from "@/contexts/AuthContext";
27	import { canDeployConfig } from "@/utils/accessControl";
28	import type { EntityKind, SectionState, Selection } from "./builderPageTypes";
29	
30	// ---------- Component ----------
31	
32	const BuilderPage: React.FC = () => {
33	  const {
34	    dslSource,
35	    diagnostics,
36	    symbols,
37	    ast,
38	    baseConfigYaml,
39	    wasmReady,
40	    wasmError,
41	    loading,
42	    mode,
43	    dirty,
44	    yamlOutput,
45	    crdOutput,
46	    compileError,
47	    initWasm,
48	    compile,
49	    validate,
50	    parseAST,
51	    format,
52	    reset,
53	    setMode,
54	    importYaml,
55	    loadFromRouter,
56	    mutateModel,
57	    addModel,
58	    deleteModel,
59	    mutateSignal,
60	    addSignal,
61	    deleteSignal,
62	    mutateProjectionPartition,
63	    addProjectionPartition,
64	    deleteProjectionPartition,
65	    mutateProjectionScore,
66	    addProjectionScore,
67	    deleteProjectionScore,
68	    mutateProjectionMapping,
69	    addProjectionMapping,
70	    deleteProjectionMapping,
71	    mutatePlugin,
72	    addPlugin,
73	    deletePlugin,
74	    deleteRoute,
75	    mutateRoute,
76	    addRoute,
77	    requestDeploy,
78	    executeDeploy,
79	    dismissDeploy,
80	    deploying,
81	    deployStep,
82	    deployResult,
83	    showDeployConfirm,
84	    deployPreviewCurrent,
85	    deployPreviewMerged,
86	    deployPreviewLoading,
87	    deployPreviewError,
88	    nlGenerating,
89	    nlGenerateError,
90	    nlProgressEvents,
91	    nlStagedDraft,
92	    generateFromNaturalLanguage,
93	    applyNaturalLanguageDraft,
94	    discardNaturalLanguageDraft,
95	  } = useDSLStore();
96	  const { isReadonly, isLoading: readonlyLoading } = useReadonly();
97	  const { user } = useAuth();
98	  const hasDeployPermission = canDeployConfig(user);
99	
100	  const [selection, setSelection] = useState<Selection | null>(null);
101	  const [sections, setSections] = useState<SectionState>({
102	    models: true,
103	    signals: true,
104	    projectionPartitions: true,
105	    projectionScores: true,
106	    projectionMappings: true,
107	    routes: true,
108	    plugins: true,
109	  });
110	  const [addingEntity, setAddingEntity] = useState<EntityKind | null>(null);
111	  const [outputPanelOpen, setOutputPanelOpen] = useState(true);
112	  const [showImportModal, setShowImportModal] = useState(false);
113	  const [guideOpen, setGuideOpen] = useState(false);
114	
115	  const contentRef = useRef<HTMLDivElement>(null);
116	  const { width: guideWidth, isDragging: isGuideDragging, handleDragStart: handleGuideDragStart } =
117	    useResizableWidth({
118	      initialWidth: 420,
119	      minWidth: 300,
120	      getMaxWidth: () => 800,
121	      stopPropagation: true,
122	    });
123	  const { width: outputWidth, isDragging, handleDragStart } = useResizableWidth({
124	    initialWidth: 380,
125	    minWidth: 200,
126	    getMaxWidth: () =>
127	      Math.floor((contentRef.current?.offsetWidth ?? window.innerWidth) * 0.6),
128	  });
129	  const [importText, setImportText] = useState("");
130	  const [importError, setImportError] = useState<string | null>(null);
131	  const [importUrl, setImportUrl] = useState("");
132	  const [importUrlLoading, setImportUrlLoading] = useState(false);
133	  const importTextareaRef = useRef<HTMLTextAreaElement | null>(null);
134	  const fileInputRef = useRef<HTMLInputElement | null>(null);
135	  const autoLoadedDefaultConfigRef = useRef(false);
136	  const autoLoadingDefaultConfigRef = useRef(false);
137	  const isNaturalLanguageMode = mode === "nl";
138	
139	  // Initialize WASM on mount
140	  useEffect(() => {
141	    initWasm();
142	  }, [initWasm]);
143	
144	  // Always land on the DSL editor when entering the builder page.
145	  useEffect(() => {
146	    setMode("dsl");
147	  }, [setMode]);
148	
149	  // Parse AST when entering visual mode or when dslSource changes in visual mode
150	  useEffect(() => {
151	    if (mode === "visual" && wasmReady && dslSource.trim()) {
152	      parseAST();
153	    }
154	  }, [mode, wasmReady, dslSource, parseAST]);
155	
156	  useEffect(() => {
157	    if (!isNaturalLanguageMode) {
158	      return;
159	    }
160	    setGuideOpen(false);
161	    setOutputPanelOpen(false);
162	  }, [isNaturalLanguageMode]);
163	
164	  const toggleSection = useCallback((key: keyof SectionState) => {
165	    setSections((prev) => ({ ...prev, [key]: !prev[key] }));
166	  }, []);
167	
168	  const handleModeSwitch = useCallback(
169	    (newMode: EditorMode) => {
170	      setMode(newMode);
171	      setOutputPanelOpen(newMode !== "nl");
172	      // When switching to visual, parse AST
173	      if (newMode === "visual" && wasmReady && dslSource.trim()) {
174	        parseAST();
175	      }
176	    },
177	    [setMode, wasmReady, dslSource, parseAST],
178	  );
179	  const hasPendingNLDraft = nlStagedDraft !== null;
180	  const deployDisabled =
181	    readonlyLoading || isReadonly || !hasDeployPermission || hasPendingNLDraft;
182	
183	  // --- Entity CRUD handlers ---
184	
185	  const handleDeleteEntity = useCallback(
186	    (kind: EntityKind, name: string, subType?: string) => {
187	      switch (kind) {
188	        case "model":
189	          deleteModel(name);
190	          break;
191	        case "signal":
192	          if (subType) deleteSignal(subType, name);
193	          break;
194	        case "projection-partition":
195	          deleteProjectionPartition(name);
196	          break;
197	        case "projection-score":
198	          deleteProjectionScore(name);
199	          break;
200	        case "projection-mapping":
201	          deleteProjectionMapping(name);
202	          break;
203	        case "route":
204	          deleteRoute(name);
205	          break;
206	        case "plugin":
207	          if (subType) deletePlugin(name, subType);
208	          break;
209	      }
210	      setSelection(null);
211	    },
212	    [
213	      deleteModel,
214	      deleteSignal,
215	      deleteProjectionPartition,
216	      deleteProjectionScore,
217	      deleteProjectionMapping,
218	      deleteRoute,
219	      deletePlugin,
220	    ],
221	  );
222	
223	  const handleUpdateModelFields = useCallback(
224	    (name: string, fields: DSLFieldObject) => {
225	      mutateModel(name, fields);
226	    },
227	    [mutateModel],
228	  );
229	
230	  const handleAddModel = useCallback(
231	    (name: string, fields: DSLFieldObject) => {
232	      addModel(name, fields);
233	      setSelection({ kind: "model", name });
234	      setAddingEntity(null);
235	    },
236	    [addModel],
237	  );
238	
239	  const handleUpdateSignalFields = useCallback(
240	    (signalType: string, name: string, fields: DSLFieldObject) => {
241	      mutateSignal(signalType, name, fields);
242	    },
243	    [mutateSignal],
244	  );
245	
246	  const handleUpdatePluginFields = useCallback(
247	    (name: string, pluginType: string, fields: DSLFieldObject) => {
248	      mutatePlugin(name, pluginType, fields);
249	    },
250	    [mutatePlugin],
251	  );
252	
253	  const handleUpdateProjectionPartitionFields = useCallback(
254	    (name: string, fields: DSLFieldObject) => {
255	      mutateProjectionPartition(name, fields);
256	    },
257	    [mutateProjectionPartition],
258	  );
259	
260	  const handleUpdateProjectionScoreFields = useCallback(
261	    (name: string, fields: DSLFieldObject) => {
262	      mutateProjectionScore(name, fields);
263	    },
264	    [mutateProjectionScore],
265	  );
266	
267	  const handleUpdateProjectionMappingFields = useCallback(
268	    (name: string, fields: DSLFieldObject) => {
269	      mutateProjectionMapping(name, fields);
270	    },
271	    [mutateProjectionMapping],
272	  );
273	
274	  const handleAddSignal = useCallback(
275	    (signalType: string, name: string, fields: DSLFieldObject) => {
276	      addSignal(signalType, name, fields);
277	      setSelection({ kind: "signal", name });
278	      setAddingEntity(null);
279	    },
280	    [addSignal],
281	  );
282	
283	  const handleAddPlugin = useCallback(
284	    (name: string, pluginType: string, fields: DSLFieldObject) => {
285	      addPlugin(name, pluginType, fields);
286	      setSelection({ kind: "plugin", name });
287	      setAddingEntity(null);
288	    },
289	    [addPlugin],
290	  );
291	
292	  const handleAddProjectionPartition = useCallback(
293	    (name: string, fields: DSLFieldObject) => {
294	      addProjectionPartition(name, fields);
295	      setSelection({ kind: "projection-partition", name });
296	      setAddingEntity(null);
297	    },
298	    [addProjectionPartition],
299	  );
300	
301	  const handleAddProjectionScore = useCallback(
302	    (name: string, fields: DSLFieldObject) => {
303	      addProjectionScore(name, fields);
304	      setSelection({ kind: "projection-score", name });
305	      setAddingEntity(null);
306	    },
307	    [addProjectionScore],
308	  );
309	
310	  const handleAddProjectionMapping = useCallback(
311	    (name: string, fields: DSLFieldObject) => {
312	      addProjectionMapping(name, fields);
313	      setSelection({ kind: "projection-mapping", name });
314	      setAddingEntity(null);
315	    },
316	    [addProjectionMapping],
317	  );
318	
319	  const handleUpdateRoute = useCallback(
320	    (name: string, input: RouteInput) => {
321	      mutateRoute(name, input);
322	    },
323	    [mutateRoute],
324	  );
325	
326	  const handleAddRoute = useCallback(
327	    (name: string, input: RouteInput) => {
328	      addRoute(name, input);
329	      setSelection({ kind: "route", name });
330	      setAddingEntity(null);
331	    },
332	    [addRoute],
333	  );
334	
335	  // --- Import Config handlers ---
336	
337	  const handleOpenImport = useCallback(() => {
338	    setImportText("");
339	    setImportError(null);
340	    setImportUrl("");
341	    setImportUrlLoading(false);
342	    setShowImportModal(true);
343	    setTimeout(() => importTextareaRef.current?.focus(), 50);
344	  }, []);
345	
346	  const handleImportConfirm = useCallback(() => {
347	    const yaml = importText.trim();
348	    if (!yaml) {
349	      setImportError("Please paste YAML content");
350	      return;
351	    }
352	    try {
353	      importYaml(yaml);
354	      compile();
355	      setShowImportModal(false);
356	      setImportText("");
357	      setImportError(null);
358	    } catch {
359	      setImportError(
360	        "Failed to import YAML. Use a full router config or routing fragment; only the routing section is imported into DSL.",
361	      );
362	    }
363	  }, [importText, importYaml, compile]);
364	
365	  const handleImportFile = useCallback(
366	    (e: React.ChangeEvent<HTMLInputElement>) => {
367	      const file = e.target.files?.[0];
368	      if (!file) return;
369	      const reader = new FileReader();
370	      reader.onload = (ev) => {
371	        const text = ev.target?.result;
372	        if (typeof text === "string") {
373	          setImportText(text);
374	          setImportError(null);
375	        }
376	      };
377	      reader.readAsText(file);
378	      e.target.value = "";
379	    },
380	    [],
381	  );
382	
383	  const handleImportUrl = useCallback(async () => {
384	    const url = importUrl.trim();
385	    if (!url) {
386	      setImportError("Please enter a URL");
387	      return;
388	    }
389	    try {
390	      new URL(url);
391	    } catch {
392	      setImportError("Invalid URL format");
393	      return;
394	    }
395	    setImportUrlLoading(true);
396	    setImportError(null);
397	    try {
398	      const resp = await fetch("/api/tools/fetch-raw", {
399	        method: "POST",
400	        headers: { "Content-Type": "application/json" },
401	        body: JSON.stringify({ url }),
402	      });
403	      const data = await resp.json();
404	      if (data.error) {
405	        throw new Error(data.error);
406	      }
407	      if (!data.content?.trim()) {
408	        throw new Error("Remote returned empty content");
409	      }
410	      setImportText(data.content);
411	      setImportError(null);
412	    } catch (err) {
413	      setImportError(
414	        `Failed to fetch: ${err instanceof Error ? err.message : String(err)}`,
415	      );
416	    } finally {
417	      setImportUrlLoading(false);
418	    }
419	  }, [importUrl]);
420	
421	  const [loadingFromRouter, setLoadingFromRouter] = useState(false);
422	  const handleLoadFromRouter = useCallback(async () => {
423	    setLoadingFromRouter(true);
424	    setImportError(null);
425	    try {
426	      await loadFromRouter();
427	      compile();
428	      setShowImportModal(false);
429	      setImportText("");
430	    } catch (err) {
431	      setImportError(
432	        `Failed to load from router: ${err instanceof Error ? err.message : String(err)}`,
433	      );
434	    } finally {
435	      setLoadingFromRouter(false);
436	    }
437	  }, [loadFromRouter, compile]);
438	
439	  const handleRequestDeploy = useCallback(() => {
440	    if (deployDisabled) {
441	      return;
442	    }
443	    requestDeploy();
444	  }, [deployDisabled, requestDeploy]);
445	
446	  // On first entry, load current router config and compile it by default.
447	  useEffect(() => {
448	    if (
449	      !wasmReady ||
450	      readonlyLoading ||
451	      dslSource.trim() ||
452	      autoLoadedDefaultConfigRef.current ||
453	      autoLoadingDefaultConfigRef.current
454	    ) {
455	      return;
456	    }
457	
458	    autoLoadingDefaultConfigRef.current = true;
459	    let cancelled = false;
460	    const loadDefaultConfig = async () => {
461	      setLoadingFromRouter(true);
462	      setImportError(null);
463	      try {
464	        await loadFromRouter();
465	        if (!cancelled) {
466	          compile();
467	          autoLoadedDefaultConfigRef.current = true;
468	        }
469	      } catch (err) {
470	        console.error(
471	          "[BuilderPage] Failed to load default router config:",
472	          err,
473	        );
474	      } finally {
475	        autoLoadingDefaultConfigRef.current = false;
476	        if (!cancelled) {
477	          setLoadingFromRouter(false);
478	        }
479	      }
480	    };
481	    void loadDefaultConfig();
482	    return () => {
483	      cancelled = true;
484	    };
485	  }, [wasmReady, readonlyLoading, dslSource, loadFromRouter, compile]);
486	
487	  // Diagnostic counts
488	  const validationErrorCount = diagnostics.filter((d) => d.level === "error").length;
489	  const errorCount = validationErrorCount + (compileError ? 1 : 0);
490	  const modelCount = ast?.models?.length ?? symbols?.models?.length ?? 0;
491	  const currentModelNames = useMemo(() => {
492	    const rawNames = ast?.models?.map((model) => model.name) ?? symbols?.models ?? [];
493	    return Array.from(
494	      new Set(rawNames.map((name) => name.trim()).filter(Boolean)),
495	    );
496	  }, [ast?.models, symbols?.models]);
497	  const signalCount = ast?.signals?.length ?? symbols?.signals?.length ?? 0;
498	  const projectionPartitionCount = ast?.projectionPartitions?.length ?? 0;
499	  const projectionScoreCount = ast?.projectionScores?.length ?? 0;
500	  const projectionMappingCount = ast?.projectionMappings?.length ?? 0;
501	  const routeCount = ast?.routes?.length ?? symbols?.routes?.length ?? 0;
502	  const pluginCount = ast?.plugins?.length ?? symbols?.plugins?.length ?? 0;
503	  const isValid = errorCount === 0 && wasmReady;
504	  const lineCount = dslSource.split("\n").length;
505	
506	  // Memoize selected entity from AST
507	  const selectedEntity = useMemo(() => {
508	    if (!selection || !ast) return null;
509	    switch (selection.kind) {
510	      case "model":
511	        return ast.models?.find((m) => m.name === selection.name) ?? null;
512	      case "signal":
513	        return ast.signals?.find((s) => s.name === selection.name) ?? null;
514	      case "projection-partition":
515	        return ast.projectionPartitions?.find((partition) => partition.name === selection.name) ?? null;
516	      case "projection-score":
517	        return ast.projectionScores?.find((score) => score.name === selection.name) ?? null;
518	      case "projection-mapping":
519	        return ast.projectionMappings?.find((mapping) => mapping.name === selection.name) ?? null;
520	      case "route":
521	        return ast.routes?.find((r) => r.name === selection.name) ?? null;
522	      case "plugin":
523	        return ast.plugins?.find((p) => p.name === selection.name) ?? null;
524	      default:
525	        return null;
526	    }
527	  }, [selection, ast]);
528	
529	  return (
530	    <div className={styles.page}>
531	      <BuilderToolbar
532	        dirty={dirty}
533	        mode={mode}
534	        wasmReady={wasmReady}
535	        wasmError={wasmError}
536	        dslSource={dslSource}
537	        loading={loading}
538	        deploying={deploying}
539	        deployDisabled={deployDisabled}
540	        deployDisabledReason={
541	          isReadonly
542	            ? "Deploy is unavailable in read-only mode"
543	            : !hasDeployPermission
544	              ? "Deploy requires the config.deploy permission"
545	              : hasPendingNLDraft
546	                ? "Apply or discard the staged NL draft before deploying the live Builder config"
547	                : readonlyLoading
548	                  ? "Checking deploy permissions..."
549	                  : undefined
550	        }
551	        showBuilderSecondaryActions={!isNaturalLanguageMode}
552	        guideOpen={guideOpen}
553	        outputPanelOpen={!isNaturalLanguageMode && outputPanelOpen}
554	        onModeSwitch={handleModeSwitch}
555	        onImport={handleOpenImport}
556	        onCompile={compile}
557	        onRequestDeploy={handleRequestDeploy}
558	        onFormat={format}
559	        onValidate={validate}
560	        onToggleGuide={() => setGuideOpen(!guideOpen)}
561	        onToggleOutput={() => setOutputPanelOpen(!outputPanelOpen)}
562	        onReset={reset}
563	      />
564	
565	      {/* Main Content — editor + output panel */}
566	      <div className={styles.content} ref={contentRef}>
567	        {/* Editor area (switches by mode) */}
568	        <div className={styles.editorArea}>
569	          {mode === "visual" && (
570	            <VisualMode
571	              ast={ast}
572	              dslSource={dslSource}
573	              diagnostics={diagnostics}
574	              selection={selection}
575	              onSelect={setSelection}
576	              sections={sections}
577	              onToggleSection={toggleSection}
578	              selectedEntity={selectedEntity}
579	              modelCount={modelCount}
580	              signalCount={signalCount}
581	              projectionPartitionCount={projectionPartitionCount}
582	              projectionScoreCount={projectionScoreCount}
583	              projectionMappingCount={projectionMappingCount}
584	              routeCount={routeCount}
585	              pluginCount={pluginCount}
586	              wasmReady={wasmReady}
587	              wasmError={wasmError}
588	              addingEntity={addingEntity}
589	              onSetAddingEntity={setAddingEntity}
590	              onDeleteEntity={handleDeleteEntity}
591	              onUpdateModelFields={handleUpdateModelFields}
592	              onUpdateSignalFields={handleUpdateSignalFields}
593	              onUpdateProjectionPartitionFields={handleUpdateProjectionPartitionFields}
594	              onUpdateProjectionScoreFields={handleUpdateProjectionScoreFields}
595	              onUpdateProjectionMappingFields={handleUpdateProjectionMappingFields}
596	              onUpdatePluginFields={handleUpdatePluginFields}
597	              onAddModel={handleAddModel}
598	              onAddSignal={handleAddSignal}
599	              onAddProjectionPartition={handleAddProjectionPartition}
600	              onAddProjectionScore={handleAddProjectionScore}
601	              onAddProjectionMapping={handleAddProjectionMapping}
602	              onAddPlugin={handleAddPlugin}
603	              onUpdateRoute={handleUpdateRoute}
604	              onAddRoute={handleAddRoute}
605	              errorCount={errorCount}
606	              isValid={isValid}
607	              onModeSwitch={handleModeSwitch}
608	            />
609	          )}
610	          {mode === "dsl" && (
611	            <div className={styles.dslModeContainer}>
612	              <DslEditorPage embedded hideOutput />
613	            </div>
614	          )}
615	          {mode === "nl" && (
616	            <BuilderNaturalLanguagePanel
617	              currentDsl={dslSource}
618	              baseConfigYaml={baseConfigYaml}
619	              currentModelNames={currentModelNames}
620	              wasmReady={wasmReady}
621	              generating={nlGenerating}
622	              error={nlGenerateError}
623	              progressEvents={nlProgressEvents}
624	              stagedDraft={nlStagedDraft}
625	              onGenerate={generateFromNaturalLanguage}
626	              onApplyDraft={applyNaturalLanguageDraft}
627	              onDiscardDraft={discardNaturalLanguageDraft}
628	              onModeSwitch={handleModeSwitch}
629	            />
630	          )}
631	        </div>
632	
633	        {!isNaturalLanguageMode ? (
634	          <BuilderOutputPanel
635	            open={outputPanelOpen}
636	            width={outputWidth}
637	            yamlOutput={yamlOutput}
638	            crdOutput={crdOutput}
639	            dslSource={dslSource}
640	            dslTabLabel="DSL"
641	            compileError={compileError}
642	            onDragStart={handleDragStart}
643	            onOpen={() => setOutputPanelOpen(true)}
644	            onClose={() => setOutputPanelOpen(false)}
645	          />
646	        ) : null}
647	      </div>
648	
649	      <BuilderStatusBar
650	        isValid={isValid}
651	        errorCount={errorCount}
652	        modelCount={modelCount}
653	        signalCount={signalCount}
654	        routeCount={routeCount}
655	        pluginCount={pluginCount}
656	        lineCount={lineCount}
657	        mode={mode}
658	      />
659	
660	      {/* Hidden file input for YAML import */}
661	      <input
662	        ref={fileInputRef}
663	        type="file"
664	        accept=".yaml,.yml,.json"
665	        style={{ display: "none" }}
666	        onChange={handleImportFile}
667	      />
668	
669	      <BuilderImportModal
670	        open={showImportModal}
671	        importUrl={importUrl}
672	        importText={importText}
673	        importError={importError}
674	        importUrlLoading={importUrlLoading}
675	        loadingFromRouter={loadingFromRouter}
676	        importTextareaRef={importTextareaRef}
677	        onClose={() => setShowImportModal(false)}
678	        onImportUrlChange={(value) => {
679	          setImportUrl(value);
680	          setImportError(null);
681	        }}
682	        onImportTextChange={(value) => {
683	          setImportText(value);
684	          setImportError(null);
685	        }}
686	        onImportUrl={handleImportUrl}
687	        onSelectFile={() => fileInputRef.current?.click()}
688	        onLoadFromRouter={handleLoadFromRouter}
689	        onConfirm={handleImportConfirm}
690	      />
691	
692	      <BuilderGuideDrawer
693	        open={!isNaturalLanguageMode && guideOpen}
694	        width={guideWidth}
695	        isDragging={isGuideDragging}
696	        onClose={() => setGuideOpen(false)}
697	        onDragStart={handleGuideDragStart}
698	        onInsertSnippet={(snippet) => {
699	          if (mode !== "dsl") setMode("dsl");
