import React, {
  useEffect,
  useCallback,
  useState,
  useMemo,
  useRef,
} from "react";

import { useDSLStore } from "@/stores/dslStore";
import type { DSLFieldObject } from "@/types/dsl";
import type { EditorMode } from "@/types/dsl";
import type { RouteInput } from "@/lib/dslMutations";

import styles from "./BuilderPage.module.css";
import DslEditorPage from "./DslEditorPage";
import { BuilderDeployConfirmModal, BuilderDeployToast, BuilderDragOverlay } from "./builderPageDeployOverlays";
import { VisualMode } from "./builderPageVisualShell";
import { BuilderGuideDrawer } from "./builderPageGuideDrawer";
import { BuilderImportModal } from "./builderPageImportModal";
import { BuilderNaturalLanguagePanel } from "./builderPageNaturalLanguagePanel";
import { BuilderOutputPanel } from "./builderPageOutputPanel";
import { useResizableWidth } from "./builderPageResizeHooks";
import { BuilderStatusBar } from "./builderPageStatusBar";
import { BuilderToolbar } from "./builderPageToolbar";
import { useReadonly } from "@/contexts/ReadonlyContext";
import { useAuth } from "@/contexts/AuthContext";
import { canDeployConfig } from "@/utils/accessControl";
import type { EntityKind, SectionState, Selection } from "./builderPageTypes";

// ---------- Component ----------

const BuilderPage: React.FC = () => {
  const {
    dslSource,
    diagnostics,
    symbols,
    ast,
    baseConfigYaml,
    wasmReady,
    wasmError,
    loading,
    mode,
    dirty,
    yamlOutput,
    crdOutput,
    compileError,
    initWasm,
    compile,
    validate,
    parseAST,
    format,
    reset,
    setMode,
    importYaml,
    loadFromRouter,
    mutateModel,
    addModel,
    deleteModel,
    mutateSignal,
    addSignal,
    deleteSignal,
    mutateProjectionPartition,
    addProjectionPartition,
    deleteProjectionPartition,
    mutateProjectionScore,
    addProjectionScore,
    deleteProjectionScore,
    mutateProjectionMapping,
    addProjectionMapping,
    deleteProjectionMapping,
    mutatePlugin,
    addPlugin,
    deletePlugin,
    deleteRoute,
    mutateRoute,
    addRoute,
    requestDeploy,
    executeDeploy,
    dismissDeploy,
    deploying,
    deployStep,
    deployResult,
    showDeployConfirm,
    deployPreviewCurrent,
    deployPreviewMerged,
    deployPreviewLoading,
    deployPreviewError,
    nlGenerating,
    nlGenerateError,
    nlProgressEvents,
    nlStagedDraft,
    generateFromNaturalLanguage,
    applyNaturalLanguageDraft,
    discardNaturalLanguageDraft,
  } = useDSLStore();
  const { isReadonly, isLoading: readonlyLoading } = useReadonly();
  const { user } = useAuth();
  const hasDeployPermission = canDeployConfig(user);

  const [selection, setSelection] = useState<Selection | null>(null);
  const [sections, setSections] = useState<SectionState>({
    models: true,
    signals: true,
    projectionPartitions: true,
    projectionScores: true,
    projectionMappings: true,
    routes: true,
    plugins: true,
  });
  const [addingEntity, setAddingEntity] = useState<EntityKind | null>(null);
  const [outputPanelOpen, setOutputPanelOpen] = useState(true);
  const [showImportModal, setShowImportModal] = useState(false);
  const [guideOpen, setGuideOpen] = useState(false);

  const contentRef = useRef<HTMLDivElement>(null);
  const { width: guideWidth, isDragging: isGuideDragging, handleDragStart: handleGuideDragStart } =
    useResizableWidth({
      initialWidth: 420,
      minWidth: 300,
      getMaxWidth: () => 800,
      stopPropagation: true,
    });
  const { width: outputWidth, isDragging, handleDragStart } = useResizableWidth({
    initialWidth: 380,
    minWidth: 200,
    getMaxWidth: () =>
      Math.floor((contentRef.current?.offsetWidth ?? window.innerWidth) * 0.6),
  });
  const [importText, setImportText] = useState("");
  const [importError, setImportError] = useState<string | null>(null);
  const [importUrl, setImportUrl] = useState("");
  const [importUrlLoading, setImportUrlLoading] = useState(false);
  const importTextareaRef = useRef<HTMLTextAreaElement | null>(null);
  const fileInputRef = useRef<HTMLInputElement | null>(null);
  const autoLoadedDefaultConfigRef = useRef(false);
  const autoLoadingDefaultConfigRef = useRef(false);
  const isNaturalLanguageMode = mode === "nl";

  // Initialize WASM on mount
  useEffect(() => {
    initWasm();
  }, [initWasm]);

  // Always land on the DSL editor when entering the builder page.
  useEffect(() => {
    setMode("dsl");
  }, [setMode]);

  // Parse AST when entering visual mode or when dslSource changes in visual mode
  useEffect(() => {
    if (mode === "visual" && wasmReady && dslSource.trim()) {
      parseAST();
    }
  }, [mode, wasmReady, dslSource, parseAST]);

  useEffect(() => {
    if (!isNaturalLanguageMode) {
      return;
    }
    setGuideOpen(false);
    setOutputPanelOpen(false);
  }, [isNaturalLanguageMode]);

  const toggleSection = useCallback((key: keyof SectionState) => {
    setSections((prev) => ({ ...prev, [key]: !prev[key] }));
  }, []);

  const handleModeSwitch = useCallback(
    (newMode: EditorMode) => {
      setMode(newMode);
      setOutputPanelOpen(newMode !== "nl");
      // When switching to visual, parse AST
      if (newMode === "visual" && wasmReady && dslSource.trim()) {
        parseAST();
      }
    },
    [setMode, wasmReady, dslSource, parseAST],
  );
  const hasPendingNLDraft = nlStagedDraft !== null;
  const deployDisabled =
    readonlyLoading || isReadonly || !hasDeployPermission || hasPendingNLDraft;

  // --- Entity CRUD handlers ---

  const handleDeleteEntity = useCallback(
    (kind: EntityKind, name: string, subType?: string) => {
      switch (kind) {
        case "model":
          deleteModel(name);
          break;
        case "signal":
          if (subType) deleteSignal(subType, name);
          break;
        case "projection-partition":
          deleteProjectionPartition(name);
          break;
        case "projection-score":
          deleteProjectionScore(name);
          break;
        case "projection-mapping":
          deleteProjectionMapping(name);
          break;
        case "route":
          deleteRoute(name);
          break;
        case "plugin":
          if (subType) deletePlugin(name, subType);
          break;
      }
      setSelection(null);
    },
    [
      deleteModel,
      deleteSignal,
      deleteProjectionPartition,
      deleteProjectionScore,
      deleteProjectionMapping,
      deleteRoute,
      deletePlugin,
    ],
  );

  const handleUpdateModelFields = useCallback(
    (name: string, fields: DSLFieldObject) => {
      mutateModel(name, fields);
    },
    [mutateModel],
  );

  const handleAddModel = useCallback(
    (name: string, fields: DSLFieldObject) => {
      addModel(name, fields);
      setSelection({ kind: "model", name });
      setAddingEntity(null);
    },
    [addModel],
  );

  const handleUpdateSignalFields = useCallback(
    (signalType: string, name: string, fields: DSLFieldObject) => {
      mutateSignal(signalType, name, fields);
    },
    [mutateSignal],
  );

  const handleUpdatePluginFields = useCallback(
    (name: string, pluginType: string, fields: DSLFieldObject) => {
      mutatePlugin(name, pluginType, fields);
    },
    [mutatePlugin],
  );

  const handleUpdateProjectionPartitionFields = useCallback(
    (name: string, fields: DSLFieldObject) => {
      mutateProjectionPartition(name, fields);
    },
    [mutateProjectionPartition],
  );

  const handleUpdateProjectionScoreFields = useCallback(
    (name: string, fields: DSLFieldObject) => {
      mutateProjectionScore(name, fields);
    },
    [mutateProjectionScore],
  );

  const handleUpdateProjectionMappingFields = useCallback(
    (name: string, fields: DSLFieldObject) => {
      mutateProjectionMapping(name, fields);
    },
    [mutateProjectionMapping],
  );

  const handleAddSignal = useCallback(
    (signalType: string, name: string, fields: DSLFieldObject) => {
      addSignal(signalType, name, fields);
      setSelection({ kind: "signal", name });
      setAddingEntity(null);
    },
    [addSignal],
  );

  const handleAddPlugin = useCallback(
    (name: string, pluginType: string, fields: DSLFieldObject) => {
      addPlugin(name, pluginType, fields);
      setSelection({ kind: "plugin", name });
      setAddingEntity(null);
    },
    [addPlugin],
  );

  const handleAddProjectionPartition = useCallback(
    (name: string, fields: DSLFieldObject) => {
      addProjectionPartition(name, fields);
      setSelection({ kind: "projection-partition", name });
      setAddingEntity(null);
    },
    [addProjectionPartition],
  );

  const handleAddProjectionScore = useCallback(
    (name: string, fields: DSLFieldObject) => {
      addProjectionScore(name, fields);
      setSelection({ kind: "projection-score", name });
      setAddingEntity(null);
    },
    [addProjectionScore],
  );

  const handleAddProjectionMapping = useCallback(
    (name: string, fields: DSLFieldObject) => {
      addProjectionMapping(name, fields);
      setSelection({ kind: "projection-mapping", name });
      setAddingEntity(null);
    },
    [addProjectionMapping],
  );

  const handleUpdateRoute = useCallback(
    (name: string, input: RouteInput) => {
      mutateRoute(name, input);
    },
    [mutateRoute],
  );

  const handleAddRoute = useCallback(
    (name: string, input: RouteInput) => {
      addRoute(name, input);
      setSelection({ kind: "route", name });
      setAddingEntity(null);
    },
    [addRoute],
  );

  // --- Import Config handlers ---

  const handleOpenImport = useCallback(() => {
    setImportText("");
    setImportError(null);
    setImportUrl("");
    setImportUrlLoading(false);
    setShowImportModal(true);
    setTimeout(() => importTextareaRef.current?.focus(), 50);
  }, []);

  const handleImportConfirm = useCallback(() => {
    const yaml = importText.trim();
    if (!yaml) {
      setImportError("Please paste YAML content");
      return;
    }
    try {
      importYaml(yaml);
      compile();
      setShowImportModal(false);
      setImportText("");
      setImportError(null);
    } catch {
      setImportError(
        "Failed to import YAML. Use a full router config or routing fragment; only the routing section is imported into DSL.",
      );
    }
  }, [importText, importYaml, compile]);

  const handleImportFile = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (ev) => {
        const text = ev.target?.result;
        if (typeof text === "string") {
          setImportText(text);
          setImportError(null);
        }
      };
      reader.readAsText(file);
      e.target.value = "";
    },
    [],
  );

  const handleImportUrl = useCallback(async () => {
    const url = importUrl.trim();
    if (!url) {
      setImportError("Please enter a URL");
      return;
    }
    try {
      new URL(url);
    } catch {
      setImportError("Invalid URL format");
      return;
    }
    setImportUrlLoading(true);
    setImportError(null);
    try {
      const resp = await fetch("/api/tools/fetch-raw", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }),
      });
      const data = await resp.json();
      if (data.error) {
        throw new Error(data.error);
      }
      if (!data.content?.trim()) {
        throw new Error("Remote returned empty content");
      }
      setImportText(data.content);
      setImportError(null);
    } catch (err) {
      setImportError(
        `Failed to fetch: ${err instanceof Error ? err.message : String(err)}`,
      );
    } finally {
      setImportUrlLoading(false);
    }
  }, [importUrl]);

  const [loadingFromRouter, setLoadingFromRouter] = useState(false);
  const handleLoadFromRouter = useCallback(async () => {
    setLoadingFromRouter(true);
    setImportError(null);
    try {
      await loadFromRouter();
      compile();
      setShowImportModal(false);
      setImportText("");
    } catch (err) {
      setImportError(
        `Failed to load from router: ${err instanceof Error ? err.message : String(err)}`,
      );
    } finally {
      setLoadingFromRouter(false);
    }
  }, [loadFromRouter, compile]);

  const handleRequestDeploy = useCallback(() => {
    if (deployDisabled) {
      return;
    }
    requestDeploy();
  }, [deployDisabled, requestDeploy]);

  // On first entry, load current router config and compile it by default.
  useEffect(() => {
    if (
      !wasmReady ||
      readonlyLoading ||
      dslSource.trim() ||
      autoLoadedDefaultConfigRef.current ||
      autoLoadingDefaultConfigRef.current
    ) {
      return;
    }

    autoLoadingDefaultConfigRef.current = true;
    let cancelled = false;
    const loadDefaultConfig = async () => {
      setLoadingFromRouter(true);
      setImportError(null);
      try {
        await loadFromRouter();
        if (!cancelled) {
          compile();
          autoLoadedDefaultConfigRef.current = true;
        }
      } catch (err) {
        console.error(
          "[BuilderPage] Failed to load default router config:",
          err,
        );
      } finally {
        autoLoadingDefaultConfigRef.current = false;
        if (!cancelled) {
          setLoadingFromRouter(false);
        }
      }
    };
    void loadDefaultConfig();
    return () => {
      cancelled = true;
    };
  }, [wasmReady, readonlyLoading, dslSource, loadFromRouter, compile]);

  // Diagnostic counts
  const validationErrorCount = diagnostics.filter((d) => d.level === "error").length;
  const errorCount = validationErrorCount + (compileError ? 1 : 0);
  const modelCount = ast?.models?.length ?? symbols?.models?.length ?? 0;
  const currentModelNames = useMemo(() => {
    const rawNames = ast?.models?.map((model) => model.name) ?? symbols?.models ?? [];
    return Array.from(
      new Set(rawNames.map((name) => name.trim()).filter(Boolean)),
    );
  }, [ast?.models, symbols?.models]);
  const signalCount = ast?.signals?.length ?? symbols?.signals?.length ?? 0;
  const projectionPartitionCount = ast?.projectionPartitions?.length ?? 0;
  const projectionScoreCount = ast?.projectionScores?.length ?? 0;
  const projectionMappingCount = ast?.projectionMappings?.length ?? 0;
  const routeCount = ast?.routes?.length ?? symbols?.routes?.length ?? 0;
  const pluginCount = ast?.plugins?.length ?? symbols?.plugins?.length ?? 0;
  const isValid = errorCount === 0 && wasmReady;
  const lineCount = dslSource.split("\n").length;

  // Memoize selected entity from AST
  const selectedEntity = useMemo(() => {
    if (!selection || !ast) return null;
    switch (selection.kind) {
      case "model":
        return ast.models?.find((m) => m.name === selection.name) ?? null;
      case "signal":
        return ast.signals?.find((s) => s.name === selection.name) ?? null;
      case "projection-partition":
        return ast.projectionPartitions?.find((partition) => partition.name === selection.name) ?? null;
      case "projection-score":
        return ast.projectionScores?.find((score) => score.name === selection.name) ?? null;
      case "projection-mapping":
        return ast.projectionMappings?.find((mapping) => mapping.name === selection.name) ?? null;
      case "route":
        return ast.routes?.find((r) => r.name === selection.name) ?? null;
      case "plugin":
        return ast.plugins?.find((p) => p.name === selection.name) ?? null;
      default:
        return null;
    }
  }, [selection, ast]);

  return (
    <div className={styles.page}>
      <BuilderToolbar
        dirty={dirty}
        mode={mode}
        wasmReady={wasmReady}
        wasmError={wasmError}
        dslSource={dslSource}
        loading={loading}
        deploying={deploying}
        deployDisabled={deployDisabled}
        deployDisabledReason={
          isReadonly
            ? "Deploy is unavailable in read-only mode"
            : !hasDeployPermission
              ? "Deploy requires the config.deploy permission"
              : hasPendingNLDraft
                ? "Apply or discard the staged NL draft before deploying the live Builder config"
                : readonlyLoading
                  ? "Checking deploy permissions..."
                  : undefined
        }
        showBuilderSecondaryActions={!isNaturalLanguageMode}
        guideOpen={guideOpen}
        outputPanelOpen={!isNaturalLanguageMode && outputPanelOpen}
        onModeSwitch={handleModeSwitch}
        onImport={handleOpenImport}
        onCompile={compile}
        onRequestDeploy={handleRequestDeploy}
        onFormat={format}
        onValidate={validate}
        onToggleGuide={() => setGuideOpen(!guideOpen)}
        onToggleOutput={() => setOutputPanelOpen(!outputPanelOpen)}
        onReset={reset}
      />

      {/* Main Content — editor + output panel */}
      <div className={styles.content} ref={contentRef}>
        {/* Editor area (switches by mode) */}
        <div className={styles.editorArea}>
          {mode === "visual" && (
            <VisualMode
              ast={ast}
              dslSource={dslSource}
              diagnostics={diagnostics}
              selection={selection}
              onSelect={setSelection}
              sections={sections}
              onToggleSection={toggleSection}
              selectedEntity={selectedEntity}
              modelCount={modelCount}
              signalCount={signalCount}
              projectionPartitionCount={projectionPartitionCount}
              projectionScoreCount={projectionScoreCount}
              projectionMappingCount={projectionMappingCount}
              routeCount={routeCount}
              pluginCount={pluginCount}
              wasmReady={wasmReady}
              wasmError={wasmError}
              addingEntity={addingEntity}
              onSetAddingEntity={setAddingEntity}
              onDeleteEntity={handleDeleteEntity}
              onUpdateModelFields={handleUpdateModelFields}
              onUpdateSignalFields={handleUpdateSignalFields}
              onUpdateProjectionPartitionFields={handleUpdateProjectionPartitionFields}
              onUpdateProjectionScoreFields={handleUpdateProjectionScoreFields}
              onUpdateProjectionMappingFields={handleUpdateProjectionMappingFields}
              onUpdatePluginFields={handleUpdatePluginFields}
              onAddModel={handleAddModel}
              onAddSignal={handleAddSignal}
              onAddProjectionPartition={handleAddProjectionPartition}
              onAddProjectionScore={handleAddProjectionScore}
              onAddProjectionMapping={handleAddProjectionMapping}
              onAddPlugin={handleAddPlugin}
              onUpdateRoute={handleUpdateRoute}
              onAddRoute={handleAddRoute}
              errorCount={errorCount}
              isValid={isValid}
              onModeSwitch={handleModeSwitch}
            />
          )}
          {mode === "dsl" && (
            <div className={styles.dslModeContainer}>
              <DslEditorPage embedded hideOutput />
            </div>
          )}
          {mode === "nl" && (
            <BuilderNaturalLanguagePanel
              currentDsl={dslSource}
              baseConfigYaml={baseConfigYaml}
              currentModelNames={currentModelNames}
              wasmReady={wasmReady}
              generating={nlGenerating}
              error={nlGenerateError}
              progressEvents={nlProgressEvents}
              stagedDraft={nlStagedDraft}
              onGenerate={generateFromNaturalLanguage}
              onApplyDraft={applyNaturalLanguageDraft}
              onDiscardDraft={discardNaturalLanguageDraft}
              onModeSwitch={handleModeSwitch}
            />
          )}
        </div>

        {!isNaturalLanguageMode ? (
          <BuilderOutputPanel
            open={outputPanelOpen}
            width={outputWidth}
            yamlOutput={yamlOutput}
            crdOutput={crdOutput}
            dslSource={dslSource}
            dslTabLabel="DSL"
            compileError={compileError}
            onDragStart={handleDragStart}
            onOpen={() => setOutputPanelOpen(true)}
            onClose={() => setOutputPanelOpen(false)}
          />
        ) : null}
      </div>

      <BuilderStatusBar
        isValid={isValid}
        errorCount={errorCount}
        modelCount={modelCount}
        signalCount={signalCount}
        routeCount={routeCount}
        pluginCount={pluginCount}
        lineCount={lineCount}
        mode={mode}
      />

      {/* Hidden file input for YAML import */}
      <input
        ref={fileInputRef}
        type="file"
        accept=".yaml,.yml,.json"
        style={{ display: "none" }}
        onChange={handleImportFile}
      />

      <BuilderImportModal
        open={showImportModal}
        importUrl={importUrl}
        importText={importText}
        importError={importError}
        importUrlLoading={importUrlLoading}
        loadingFromRouter={loadingFromRouter}
        importTextareaRef={importTextareaRef}
        onClose={() => setShowImportModal(false)}
        onImportUrlChange={(value) => {
          setImportUrl(value);
          setImportError(null);
        }}
        onImportTextChange={(value) => {
          setImportText(value);
          setImportError(null);
        }}
        onImportUrl={handleImportUrl}
        onSelectFile={() => fileInputRef.current?.click()}
        onLoadFromRouter={handleLoadFromRouter}
        onConfirm={handleImportConfirm}
      />

      <BuilderGuideDrawer
        open={!isNaturalLanguageMode && guideOpen}
        width={guideWidth}
        isDragging={isGuideDragging}
        onClose={() => setGuideOpen(false)}
        onDragStart={handleGuideDragStart}
        onInsertSnippet={(snippet) => {
          if (mode !== "dsl") setMode("dsl");
          const store = useDSLStore.getState();
          const src = store.dslSource;
          store.setDslSource(
            src ? src.trimEnd() + "\n\n" + snippet + "\n" : snippet + "\n",
          );
          setGuideOpen(false);
        }}
      />

      <BuilderDeployConfirmModal
        open={showDeployConfirm}
        loading={deployPreviewLoading}
        error={deployPreviewError}
        currentYaml={deployPreviewCurrent}
        mergedYaml={deployPreviewMerged}
        onClose={dismissDeploy}
        onConfirm={executeDeploy}
      />

      <BuilderDeployToast
        deploying={deploying}
        deployStep={deployStep}
        deployResult={deployResult}
        onDismiss={dismissDeploy}
      />

      <BuilderDragOverlay active={isDragging || isGuideDragging} />
    </div>
  );
};


export default BuilderPage;

import React, { useEffect, useRef, useCallback, useState } from 'react'
import Editor, { type OnMount, type BeforeMount, type Monaco } from '@monaco-editor/react'
import type * as monacoNs from 'monaco-editor'
import { useDSLStore } from '@/stores/dslStore'
import {
  registerDSLLanguage,
  defineTheme,
  DSL_LANGUAGE_ID,
  diagnosticsToMarkers,
} from '@/lib/dslLanguage'
import { DslImportModal } from './DslImportModal'
import styles from './DslEditorPage.module.css'

type OutputTab = 'yaml' | 'crd'

const DEFAULT_DSL = `# Welcome to the Signal DSL Editor
# Press Ctrl+Enter to compile, Ctrl+Shift+F to format
#
# Example:
# MODEL "gpt-4o" {
#   modality: "text"
#   capabilities: ["general", "reasoning"]
# }
#
# SIGNAL keyword math_terms {
#   keywords: ["calculus", "algebra", "geometry"]
#   operator: "OR"
#   case_sensitive: false
# }
#
# ROUTE math_route (description = "Route math queries") {
#   PRIORITY 10
#   WHEN keyword("math_terms")
#   MODEL "gpt-4o"
# }
`

interface DslEditorPageProps {
  /** When embedded in BuilderPage, hide own toolbar and status bar */
  embedded?: boolean
  /** When true, hide the output pane (YAML/CRD) — the parent provides its own */
  hideOutput?: boolean
}

const DslEditorPage: React.FC<DslEditorPageProps> = ({ embedded = false, hideOutput = false }) => {
  const {
    dslSource,
    yamlOutput,
    crdOutput,
    diagnostics,
    symbols,
    wasmReady,
    wasmError,
    loading,
    compileError,
    dirty,
    initWasm,
    setDslSource,
    compile,
    validate,
    format,
    reset,
    importYaml,
  } = useDSLStore()

  const [outputTab, setOutputTab] = useState<OutputTab>('yaml')
  const [copied, setCopied] = useState(false)
  const [showImportModal, setShowImportModal] = useState(false)
  const [importText, setImportText] = useState('')
  const [importError, setImportError] = useState<string | null>(null)
  const [importUrl, setImportUrl] = useState('')
  const [importUrlLoading, setImportUrlLoading] = useState(false)
  const [diagHeight, setDiagHeight] = useState(160)
  const diagHeightRef = useRef(diagHeight)
  const diagDragging = useRef(false)
  const diagStartY = useRef(0)
  const diagStartH = useRef(0)
  const importTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const fileInputRef = useRef<HTMLInputElement | null>(null)
  const editorRef = useRef<monacoNs.editor.IStandaloneCodeEditor | null>(null)
  const monacoRef = useRef<Monaco | null>(null)

  // Keep ref in sync with state
  useEffect(() => { diagHeightRef.current = diagHeight }, [diagHeight])

  // Drag to resize diagnostics panel
  const onDiagDragStart = useCallback((e: React.MouseEvent) => {
    e.preventDefault()
    diagDragging.current = true
    diagStartY.current = e.clientY
    diagStartH.current = diagHeightRef.current

    const onMove = (ev: MouseEvent) => {
      if (!diagDragging.current) return
      const delta = diagStartY.current - ev.clientY
      setDiagHeight(Math.max(32, Math.min(500, diagStartH.current + delta)))
    }
    const onUp = () => {
      diagDragging.current = false
      document.removeEventListener('mousemove', onMove)
      document.removeEventListener('mouseup', onUp)
    }
    document.addEventListener('mousemove', onMove)
    document.addEventListener('mouseup', onUp)
  }, [])

  // Initialize WASM on mount
  useEffect(() => {
    initWasm()
  }, [initWasm])

  // Set diagnostics as Monaco markers whenever they change
  useEffect(() => {
    const editor = editorRef.current
    const monaco = monacoRef.current
    if (!editor || !monaco) return

    const model = editor.getModel()
    if (!model) return

    const markers = diagnosticsToMarkers(monaco, diagnostics)
    monaco.editor.setModelMarkers(model, 'signal-dsl', markers)
  }, [diagnostics])

  // Keyboard shortcuts
  useEffect(() => {
    const editor = editorRef.current
    if (!editor) return

    // Ctrl+Enter → Compile
    editor.addAction({
      id: 'dsl-compile',
      label: 'Compile DSL',
      keybindings: [
        (monacoRef.current?.KeyMod.CtrlCmd ?? 0) | (monacoRef.current?.KeyCode.Enter ?? 0),
      ],
      run: () => compile(),
    })

    // Ctrl+Shift+F → Format
    editor.addAction({
      id: 'dsl-format',
      label: 'Format DSL',
      keybindings: [
        (monacoRef.current?.KeyMod.CtrlCmd ?? 0) |
          (monacoRef.current?.KeyMod.Shift ?? 0) |
          (monacoRef.current?.KeyCode.KeyF ?? 0),
      ],
      run: () => format(),
    })
  }, [compile, format, wasmReady])

  // Register theme before Monaco renders so the first paint is already dark
  const handleBeforeMount: BeforeMount = useCallback((monaco) => {
    defineTheme(monaco)
  }, [])

  const handleEditorMount: OnMount = useCallback(
    (editor, monaco) => {
      editorRef.current = editor
      monacoRef.current = monaco

      // Register DSL language with symbol table provider and diagnostics for Quick Fix
      registerDSLLanguage(
        monaco,
        () => useDSLStore.getState().symbols,
        () => useDSLStore.getState().diagnostics,
      )

      // Set model language
      const model = editor.getModel()
      if (model) {
        monaco.editor.setModelLanguage(model, DSL_LANGUAGE_ID)
      }

      // The standalone editor gets a starter template; the Builder page must
      // stay empty until its router-backed import fills the store.
      if (!embedded && !useDSLStore.getState().dslSource.trim()) {
        setDslSource(DEFAULT_DSL)
      }
    },
    [embedded, setDslSource],
  )

  const handleEditorChange = useCallback(
    (value: string | undefined) => {
      setDslSource(value ?? '')
    },
    [setDslSource],
  )

  const handleCopyOutput = useCallback(async () => {
    const text = outputTab === 'yaml' ? yamlOutput : crdOutput
    if (!text) return
    try {
      // Try Clipboard API first
      if (navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(text)
      } else {
        // Fallback for non-secure contexts (http://localhost etc.)
        const textarea = document.createElement('textarea')
        textarea.value = text
        textarea.style.position = 'fixed'
        textarea.style.opacity = '0'
        document.body.appendChild(textarea)
        textarea.select()
        document.execCommand('copy')
        document.body.removeChild(textarea)
      }
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    } catch {
      // Last-resort fallback
      const textarea = document.createElement('textarea')
      textarea.value = text
      textarea.style.position = 'fixed'
      textarea.style.opacity = '0'
      document.body.appendChild(textarea)
      textarea.select()
      document.execCommand('copy')
      document.body.removeChild(textarea)
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    }
  }, [outputTab, yamlOutput, crdOutput])

  const handleGoToLine = useCallback((line: number, column: number) => {
    const editor = editorRef.current
    if (!editor) return
    editor.revealLineInCenter(line)
    editor.setPosition({ lineNumber: line, column })
    editor.focus()
  }, [])

  const handleApplyFix = useCallback((line: number, column: number, newText: string) => {
    const editor = editorRef.current
    if (!editor) return
    const model = editor.getModel()
    if (!model) return

    // Find the word/token at the diagnostic position to replace
    const lineContent = model.getLineContent(line)
    let startCol = column
    let endCol = column
    while (startCol > 1 && /[\w\-.]/.test(lineContent[startCol - 2])) startCol--
    while (endCol <= lineContent.length && /[\w\-.]/.test(lineContent[endCol - 1])) endCol++

    editor.executeEdits('quick-fix', [{
      range: {
        startLineNumber: line,
        startColumn: startCol,
        endLineNumber: line,
        endColumn: endCol,
      },
      text: newText,
    }])
    // Trigger re-validation
    const src = model.getValue()
    setDslSource(src)
  }, [setDslSource])

  const handleOpenImport = useCallback(() => {
    setImportText('')
    setImportError(null)
    setImportUrl('')
    setImportUrlLoading(false)
    setShowImportModal(true)
    setTimeout(() => importTextareaRef.current?.focus(), 50)
  }, [])

  const handleImportConfirm = useCallback(() => {
    const yaml = importText.trim()
    if (!yaml) {
      setImportError('Please paste YAML content')
      return
    }
    try {
      importYaml(yaml)
      setShowImportModal(false)
      setImportText('')
      setImportError(null)
    } catch {
      setImportError('Failed to import YAML. Use a full router config or routing fragment; only the routing section is imported into DSL.')
    }
  }, [importText, importYaml])

  const handleImportFile = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (ev) => {
      const text = ev.target?.result
      if (typeof text === 'string') {
        setImportText(text)
        setImportError(null)
      }
    }
    reader.readAsText(file)
    // Reset file input so same file can be re-selected
    e.target.value = ''
  }, [])

  const handleImportUrl = useCallback(async () => {
    const url = importUrl.trim()
    if (!url) { setImportError('Please enter a URL'); return }
    try {
      new URL(url)
    } catch {
      setImportError('Invalid URL format'); return
    }
    setImportUrlLoading(true)
    setImportError(null)
    try {
      const resp = await fetch('/api/tools/fetch-raw', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ url }),
      })
      const data = await resp.json()
      if (data.error) {
        throw new Error(data.error)
      }
      if (!data.content?.trim()) {
        throw new Error('Remote returned empty content')
      }
      setImportText(data.content)
      setImportError(null)
    } catch (err) {
      setImportError(`Failed to fetch: ${err instanceof Error ? err.message : String(err)}`)
    } finally {
      setImportUrlLoading(false)
    }
  }, [importUrl])

  // Diagnostic counts (3 severity levels per design doc)
  const errorCount = diagnostics.filter((d) => d.level === 'error').length
  const warnCount = diagnostics.filter((d) => d.level === 'warning').length
  const constraintCount = diagnostics.filter((d) => d.level === 'constraint').length

  // Stats for status bar
  const lineCount = dslSource.split('\n').length
  const signalCount = symbols?.signals?.length ?? 0
  const routeCount = symbols?.routes?.length ?? 0
  const isValid = errorCount === 0 && wasmReady

  return (
    <div className={`${styles.page} ${embedded ? styles.embedded : ''}`}>
      {/* Toolbar — hidden when embedded in BuilderPage (parent provides toolbar) */}
      {!embedded && (
      <div className={styles.toolbar}>
        <div className={styles.toolbarTitle}>
          <svg width="16" height="16" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M2 3h12M2 8h8M2 13h10" strokeLinecap="round" />
          </svg>
          DSL Editor
          {dirty && <span style={{ color: 'var(--color-text-muted)', fontWeight: 400 }}>(unsaved)</span>}
        </div>

        {/* WASM status */}
        {wasmError ? (
          <span className={styles.statusError}>
            <span className={styles.dot} /> WASM Error
          </span>
        ) : wasmReady ? (
          <span className={styles.statusReady}>
            <span className={styles.dot} /> Ready
          </span>
        ) : (
          <span className={styles.statusLoading}>
            <span className={styles.dotPulse} /> Loading WASM…
          </span>
        )}

        <span className={styles.divider} />

        <button
          className={styles.toolbarBtn}
          onClick={handleOpenImport}
          disabled={!wasmReady}
          title="Import routing from YAML config"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M8 2v8M5 7l3 3 3-3" strokeLinecap="round" strokeLinejoin="round" />
            <path d="M2 11v2a1 1 0 001 1h10a1 1 0 001-1v-2" strokeLinecap="round" />
          </svg>
          Import YAML
        </button>

        <button
          className={styles.toolbarBtn}
          onClick={format}
          disabled={!wasmReady || !dslSource.trim()}
          title="Format (Ctrl+Shift+F)"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M2 4h12M2 8h8M2 12h10" strokeLinecap="round" />
          </svg>
          Format
        </button>

        <button
          className={styles.toolbarBtn}
          onClick={validate}
          disabled={!wasmReady || !dslSource.trim()}
          title="Validate DSL"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M3 8.5l3 3 7-7" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          Validate
        </button>

        <button
          className={styles.toolbarBtnPrimary}
          onClick={compile}
          disabled={!wasmReady || !dslSource.trim() || loading}
          title="Compile (Ctrl+Enter)"
        >
          <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
            <path d="M4 2l8 6-8 6V2z" fill="currentColor" />
          </svg>
          {loading ? 'Compiling…' : 'Compile'}
        </button>

        <span className={styles.divider} />

        <button
          className={styles.toolbarBtnDanger}
          onClick={reset}
          title="Reset editor"
        >
          Reset
        </button>
      </div>
      )}

      {/* Split panes */}
      <div className={styles.splitContainer}>
        {/* Left: Editor */}
        <div className={styles.editorPane} style={{ position: 'relative', ...(hideOutput ? { borderRight: 'none' } : {}) }}>
          <div className={styles.paneHeader}>
            <span className={styles.paneTitle}>Source</span>
          </div>

          {/* WASM loading overlay */}
          {!wasmReady && !wasmError && (
            <div className={styles.wasmOverlay}>
              <div className={styles.spinner} />
              Loading Signal Compiler…
            </div>
          )}

          <Editor
            height="100%"
            defaultLanguage={DSL_LANGUAGE_ID}
            defaultValue={embedded ? dslSource : dslSource || DEFAULT_DSL}
            value={dslSource}
            theme="signal-dsl-dark"
            onChange={handleEditorChange}
            beforeMount={handleBeforeMount}
            onMount={handleEditorMount}
            options={{
              fontSize: 13,
              fontFamily: 'var(--font-mono)',
              minimap: { enabled: false },
              lineNumbers: 'on',
              scrollBeyondLastLine: false,
              wordWrap: 'on',
              tabSize: 2,
              insertSpaces: true,
              automaticLayout: true,
              bracketPairColorization: { enabled: true },
              guides: { indentation: true, bracketPairs: true },
              suggest: { showKeywords: true, showSnippets: true },
              quickSuggestions: { strings: false, other: true, comments: false },
              padding: { top: 8, bottom: 8 },
              renderLineHighlight: 'line',
              smoothScrolling: true,
              cursorBlinking: 'smooth',
              cursorSmoothCaretAnimation: 'on',
            }}
          />

          {/* Diagnostics panel — always visible, resizable */}
          <div className={styles.diagnosticsPanel} style={{ height: diagHeight }}>
            <div className={styles.diagResizeHandle} onMouseDown={onDiagDragStart} />
            <div className={styles.diagnosticsHeader}>
              <span className={styles.diagnosticsTitle}>Problems</span>
              {errorCount > 0 ? (
                <span className={styles.diagCountError}>{errorCount} error{errorCount !== 1 ? 's' : ''}</span>
              ) : (
                <span className={styles.diagCountOk}>0 errors</span>
              )}
              {warnCount > 0 ? (
                <span className={styles.diagCountWarn}>{warnCount} warning{warnCount !== 1 ? 's' : ''}</span>
              ) : (
                <span className={styles.diagCountOk}>0 warnings</span>
              )}
              {constraintCount > 0 ? (
                <span className={styles.diagCountConstraint}>{constraintCount} constraint{constraintCount !== 1 ? 's' : ''}</span>
              ) : (
                <span className={styles.diagCountOk}>0 constraints</span>
              )}
            </div>
            {diagnostics.length > 0 && (
              <ul className={styles.diagnosticsList}>
                {diagnostics.map((d, i) => (
                  <li
                    key={i}
                    className={styles.diagnosticItem}
                    onClick={() => handleGoToLine(d.line, d.column)}
                  >
                    {d.level === 'error' ? (
                      <svg className={styles.diagIconError} viewBox="0 0 16 16" fill="currentColor">
                        <circle cx="8" cy="8" r="7" />
                        <path d="M5.5 5.5l5 5M10.5 5.5l-5 5" stroke="#fff" strokeWidth="1.5" strokeLinecap="round" />
                      </svg>
                    ) : d.level === 'warning' ? (
                      <svg className={styles.diagIconWarn} viewBox="0 0 16 16" fill="currentColor">
                        <path d="M8 1l7 13H1L8 1z" />
                        <path d="M8 6v3M8 11v1" stroke="#000" strokeWidth="1.5" strokeLinecap="round" />
                      </svg>
                    ) : (
                      <svg className={styles.diagIconConstraint} viewBox="0 0 16 16" fill="currentColor">
                        <circle cx="8" cy="8" r="7" />
                        <path d="M8 5v4M8 11v1" stroke="#000" strokeWidth="1.5" strokeLinecap="round" />
                      </svg>
                    )}
                    <span className={styles.diagMessage}>
                      {d.message}
                      {d.fixes?.map((fix, fi) => (
                        <button
                          key={fi}
                          className={styles.diagFixBtn}
                          onClick={(e) => { e.stopPropagation(); handleApplyFix(d.line, d.column, fix.newText) }}
                          title={fix.description}
                        >
                          Fix
                        </button>
                      ))}
                    </span>
                    <span className={styles.diagLocation}>Ln {d.line}, Col {d.column}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>

        {/* Right: Output (hidden when parent provides output panel) */}
        {!hideOutput && (
        <div className={styles.outputPane}>
          <div className={styles.outputTabs}>
            <button
              className={outputTab === 'yaml' ? styles.outputTabActive : styles.outputTab}
              onClick={() => setOutputTab('yaml')}
            >
              YAML Output
            </button>
            <button
              className={outputTab === 'crd' ? styles.outputTabActive : styles.outputTab}
              onClick={() => setOutputTab('crd')}
            >
              CRD Output
            </button>
            <div style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', paddingRight: 'var(--spacing-sm)' }}>
              {(outputTab === 'yaml' ? yamlOutput : crdOutput) && (
                <button className={styles.toolbarBtn} onClick={handleCopyOutput} title="Copy to clipboard">
                  {copied ? (
                    <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="var(--color-success)" strokeWidth="2">
                      <path d="M3 8.5l3 3 7-7" strokeLinecap="round" strokeLinejoin="round" />
                    </svg>
                  ) : (
                    <svg width="12" height="12" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.5">
                      <rect x="5" y="5" width="9" height="9" rx="1" />
                      <path d="M2 11V2h9" strokeLinecap="round" />
                    </svg>
                  )}
                  {copied ? 'Copied!' : 'Copy'}
                </button>
              )}
            </div>
          </div>

          <div className={styles.outputContent}>
            {compileError && (
              <div style={{ padding: 'var(--spacing-md)', color: 'var(--color-danger)', fontSize: 'var(--text-xs)', fontFamily: 'var(--font-mono)' }}>
                {compileError}
              </div>
            )}

            {outputTab === 'yaml' && yamlOutput ? (
              <pre className={styles.outputCode}>{yamlOutput}</pre>
            ) : outputTab === 'crd' && crdOutput ? (
              <pre className={styles.outputCode}>{crdOutput}</pre>
            ) : (
              <div className={styles.emptyState}>
                <div className={styles.emptyIcon} aria-hidden="true">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
                    <path d="M13 2L5 14h6l-1 8 9-13h-6V2Z" strokeLinejoin="round" />
                  </svg>
                </div>
                <div>Write DSL and press <strong>Compile</strong> to see output</div>
                <div style={{ fontSize: 'var(--text-xs)', color: 'var(--color-text-muted)' }}>
                  Ctrl+Enter to compile · Ctrl+Shift+F to format
                </div>
              </div>
            )}
          </div>
        </div>
        )}
      </div>

      {/* Status Bar — hidden when embedded in BuilderPage (parent provides status bar) */}
      {!embedded && (
      <div className={styles.statusBar}>
        <div className={`${styles.statusItem} ${isValid ? styles.statusValid : styles.statusInvalid}`}>
          {isValid ? (
            <svg className={styles.statusCheckmark} viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M3 8.5l3 3 7-7" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          ) : (
            <svg className={styles.statusCheckmark} viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M4 4l8 8M12 4l-8 8" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          )}
          {isValid ? 'Config valid' : `${errorCount} error${errorCount !== 1 ? 's' : ''}`}
        </div>
        <div className={styles.statusItem}>Signals: {signalCount}</div>
        <div className={styles.statusItem}>Routes: {routeCount}</div>
        <div className={styles.statusItem}>Lines: {lineCount}</div>
      </div>
      )}

      {/* Hidden file input for YAML import */}
      <input
        ref={fileInputRef}
        type="file"
        accept=".yaml,.yml,.json"
        style={{ display: 'none' }}
        onChange={handleImportFile}
      />

      {/* Import YAML Modal */}
      {showImportModal && (
        <DslImportModal
          importText={importText}
          importError={importError}
          importUrl={importUrl}
          importUrlLoading={importUrlLoading}
          textareaRef={importTextareaRef}
          onClose={() => setShowImportModal(false)}
          onUrlChange={(value) => {
            setImportUrl(value)
            setImportError(null)
          }}
          onFetchUrl={handleImportUrl}
          onTextChange={(value) => {
            setImportText(value)
            setImportError(null)
          }}
          onLoadFile={() => fileInputRef.current?.click()}
          onImport={handleImportConfirm}
        />
      )}
    </div>
  )
}

export default DslEditorPage

import type { ClassifierSignal, ConfigSignals, MetadataSignal } from './configPageSupport'
import styles from './ConfigPageEntrypointsRecipesSection.module.css'

interface ConfigPageRecipePolicyEditorProps {
  value: ConfigSignals
  onChange: (value: ConfigSignals) => void
}

type MetadataPredicateType = 'equals' | 'in' | 'exists'

const emptyMetadataSignal = (): MetadataSignal => ({
  name: '',
  key: '',
  predicate: { equals: '' },
})

const emptyClassifierSignal = (): ClassifierSignal => ({
  name: '',
  type: 'local',
  model_path: '',
  labels: ['SAFE', 'MATCH'],
  use_cpu: true,
})

function metadataPredicateType(signal: MetadataSignal): MetadataPredicateType {
  if (signal.predicate.in !== undefined) return 'in'
  if (signal.predicate.exists !== undefined) return 'exists'
  return 'equals'
}

function metadataPredicateForType(
  signal: MetadataSignal,
  type: MetadataPredicateType,
): MetadataSignal['predicate'] {
  if (type === 'in') return { in: signal.predicate.in ?? [] }
  if (type === 'exists') return { exists: signal.predicate.exists ?? true }
  return { equals: signal.predicate.equals ?? '' }
}

export default function ConfigPageRecipePolicyEditor({
  value,
  onChange,
}: ConfigPageRecipePolicyEditorProps) {
  const signals = value ?? {}
  const metadata = signals.metadata ?? []
  const classifiers = signals.classifiers ?? []

  const updateMetadata = (index: number, patch: Partial<MetadataSignal>) => {
    onChange({
      ...signals,
      metadata: metadata.map((signal, signalIndex) =>
        signalIndex === index ? { ...signal, ...patch } : signal,
      ),
    })
  }

  const updateClassifier = (index: number, patch: Partial<ClassifierSignal>) => {
    onChange({
      ...signals,
      classifiers: classifiers.map((signal, signalIndex) =>
        signalIndex === index ? { ...signal, ...patch } : signal,
      ),
    })
  }

  return (
    <div className={styles.decisionEditor}>
      <p className={styles.editorHint}>
        These policy signals belong only to this recipe. Existing signal families are preserved.
      </p>

      <div className={styles.modelPoolHeader}>
        <span>Metadata signals</span>
        <button
          type="button"
          className={styles.secondaryButton}
          onClick={() =>
            onChange({
              ...signals,
              metadata: [...metadata, emptyMetadataSignal()],
            })
          }
        >
          Add metadata signal
        </button>
      </div>
      <div className={styles.modelPool}>
        {metadata.map((signal, index) => {
          const predicateType = metadataPredicateType(signal)
          return (
            <article key={`${signal.name || 'metadata'}-${index}`} className={styles.decisionCard}>
              <div className={styles.editorGrid}>
                <label>
                  <span>Name</span>
                  <input
                    value={signal.name}
                    onChange={(event) => updateMetadata(index, { name: event.target.value })}
                    placeholder="tenant_tier"
                  />
                </label>
                <label>
                  <span>Metadata key</span>
                  <input
                    value={signal.key}
                    onChange={(event) => updateMetadata(index, { key: event.target.value })}
                    placeholder="tier"
                  />
                </label>
                <label>
                  <span>Predicate</span>
                  <select
                    value={predicateType}
                    onChange={(event) =>
                      updateMetadata(index, {
                        predicate: metadataPredicateForType(
                          signal,
                          event.target.value as MetadataPredicateType,
                        ),
                      })
                    }
                  >
                    <option value="equals">Equals</option>
                    <option value="in">In list</option>
                    <option value="exists">Exists</option>
                  </select>
                </label>
                {predicateType === 'equals' ? (
                  <label>
                    <span>Value</span>
                    <input
                      value={signal.predicate.equals ?? ''}
                      onChange={(event) =>
                        updateMetadata(index, {
                          predicate: { equals: event.target.value },
                        })
                      }
                    />
                  </label>
                ) : null}
                {predicateType === 'in' ? (
                  <label>
                    <span>Values</span>
                    <input
                      value={(signal.predicate.in ?? []).join(', ')}
                      onChange={(event) =>
                        updateMetadata(index, {
                          predicate: {
                            in: event.target.value
                              .split(',')
                              .map((item) => item.trim())
                              .filter(Boolean),
                          },
                        })
                      }
                      placeholder="gold, platinum"
                    />
                  </label>
                ) : null}
                {predicateType === 'exists' ? (
                  <label className={styles.checkboxControl}>
                    <input
                      type="checkbox"
                      checked={signal.predicate.exists ?? true}
                      onChange={(event) =>
                        updateMetadata(index, {
                          predicate: { exists: event.target.checked },
                        })
                      }
                    />
                    <span>Must exist</span>
                  </label>
                ) : null}
              </div>
              <button
                type="button"
                className={styles.dangerButton}
                onClick={() =>
                  onChange({
                    ...signals,
                    metadata: metadata.filter((_, signalIndex) => signalIndex !== index),
                  })
                }
              >
                Remove metadata signal
              </button>
            </article>
          )
        })}
      </div>

      <div className={styles.modelPoolHeader}>
        <span>Classifier signals</span>
        <button
          type="button"
          className={styles.secondaryButton}
          onClick={() =>
            onChange({
              ...signals,
              classifiers: [...classifiers, emptyClassifierSignal()],
            })
          }
        >
          Add classifier signal
        </button>
      </div>
      <div className={styles.modelPool}>
        {classifiers.map((signal, index) => (
          <article key={`${signal.name || 'classifier'}-${index}`} className={styles.decisionCard}>
            <div className={styles.editorGrid}>
              <label>
                <span>Name</span>
                <input
                  value={signal.name}
                  onChange={(event) => updateClassifier(index, { name: event.target.value })}
                  placeholder="risk_score"
                />
              </label>
              <label>
                <span>Classifier type</span>
                <select
                  value={signal.type}
                  onChange={(event) => {
                    const type = event.target.value as ClassifierSignal['type']
                    updateClassifier(
                      index,
                      type === 'local'
                        ? {
                            type,
                            model: undefined,
                            instructions: undefined,
                            model_path: signal.model_path ?? '',
                            use_cpu: signal.use_cpu ?? true,
                          }
                        : {
                            type,
                            model_path: undefined,
                            use_cpu: undefined,
                            model: signal.model ?? '',
                            instructions: signal.instructions ?? '',
                          },
                    )
                  }}
                >
                  <option value="local">Local</option>
                  <option value="llm">LLM</option>
                </select>
              </label>
              <label>
                <span>Labels</span>
                <input
                  value={signal.labels.join(', ')}
                  onChange={(event) =>
                    updateClassifier(index, {
                      labels: event.target.value
                        .split(',')
                        .map((item) => item.trim())
                        .filter(Boolean),
                    })
                  }
                  placeholder="SAFE, RISKY"
                />
              </label>
              {signal.type === 'local' ? (
                <>
                  <label>
                    <span>Model path</span>
                    <input
                      value={signal.model_path ?? ''}
                      onChange={(event) =>
                        updateClassifier(index, {
                          model_path: event.target.value,
                        })
                      }
                      placeholder="models/risk"
                    />
                  </label>
                  <label className={styles.checkboxControl}>
                    <input
                      type="checkbox"
                      checked={signal.use_cpu === true}
                      onChange={(event) =>
                        updateClassifier(index, {
                          use_cpu: event.target.checked,
                        })
                      }
                    />
                    <span>Use CPU</span>
                  </label>
                </>
              ) : (
                <>
                  <label>
                    <span>External model</span>
                    <input
                      value={signal.model ?? ''}
                      onChange={(event) =>
                        updateClassifier(index, {
                          model: event.target.value,
                        })
                      }
                      placeholder="classification-judge"
                    />
                  </label>
                  <label className={styles.fullWidthControl}>
                    <span>Instructions</span>
                    <textarea
                      value={signal.instructions ?? ''}
                      onChange={(event) =>
                        updateClassifier(index, {
                          instructions: event.target.value,
                        })
                      }
                      placeholder="Return one declared label."
                    />
                  </label>
                </>
              )}
            </div>
            <button
              type="button"
              className={styles.dangerButton}
              onClick={() =>
                onChange({
                  ...signals,
                  classifiers: classifiers.filter((_, signalIndex) => signalIndex !== index),
                })
              }
            >
              Remove classifier signal
            </button>
          </article>
        ))}
      </div>
    </div>
  )
}

/**
 * DSL Text-Level Mutations
 *
 * Pure functions that operate on DSL source text to add, update, and delete
 * entities (models, signals, routes, plugins). These work by finding
 * the relevant block in the DSL text using regex-based matching and brace counting,
 * then performing surgical string replacements.
 *
 * After each mutation, the caller should call parseAST() to refresh the AST.
 */

import type { BoolExprNode, DSLFieldObject, DSLFieldValue } from '@/types/dsl'

// ---------- Block finding ----------

interface BlockSpan {
  start: number  // char index of block start (e.g., "SIGNAL keyword ...")
  end: number    // char index after closing brace + newline
  body: string   // the full block text
}

/**
 * Find a top-level DSL block by construct + name.
 * E.g., findBlock(src, 'SIGNAL', 'keyword', 'urgent_request')
 *       findBlock(src, 'ROUTE', null, 'math_decision')
 */
export function findBlock(
  src: string,
  construct: 'MODEL' | 'SIGNAL' | 'ROUTE' | 'PLUGIN' | 'PROJECTION',
  subType: string | null,
  name: string | null,
): BlockSpan | null {
  // Build a regex to find the block header
  let pattern: string
  if (construct === 'MODEL') {
    pattern = `^MODEL\\s+${dslNamePattern(name!)}\\s*\\{`
  } else if (construct === 'SIGNAL' && subType) {
    pattern = name
      ? `^SIGNAL\\s+${escRe(subType)}\\s+${escRe(name)}\\s*\\{`
      : `^SIGNAL\\s+${escRe(subType)}\\s+\\S+\\s*\\{`
  } else if (construct === 'ROUTE') {
    // ROUTE name or ROUTE name (description = "...")
    pattern = `^ROUTE\\s+${escRe(name!)}\\s*(?:\\([^)]*\\))?\\s*\\{`
  } else if (construct === 'PLUGIN' && subType) {
    pattern = `^PLUGIN\\s+${escRe(name!)}\\s+${escRe(subType)}\\s*\\{`
  } else if (construct === 'PROJECTION' && subType) {
    pattern = `^PROJECTION\\s+${escRe(subType)}\\s+${dslNamePattern(name!)}\\s*\\{`
  } else {
    // Generic fallback
    const parts: string[] = [construct]
    if (subType) parts.push(escRe(subType))
    if (name) parts.push(escRe(name))
    pattern = `^${parts.join('\\s+')}\\s*\\{`
  }

  const regex = new RegExp(pattern, 'm')
  const match = regex.exec(src)
  if (!match) return null

  // Now find the matching closing brace via brace counting
  const blockStart = match.index
  let braceCount = 0
  let blockEnd = blockStart
  let foundOpenBrace = false

  for (let i = blockStart; i < src.length; i++) {
    if (src[i] === '{') {
      braceCount++
      foundOpenBrace = true
    } else if (src[i] === '}') {
      braceCount--
      if (foundOpenBrace && braceCount === 0) {
        blockEnd = i + 1
        // Include trailing newline(s)
        while (blockEnd < src.length && (src[blockEnd] === '\n' || src[blockEnd] === '\r')) {
          blockEnd++
        }
        break
      }
    }
  }

  if (!foundOpenBrace || braceCount !== 0) return null

  return {
    start: blockStart,
    end: blockEnd,
    body: src.slice(blockStart, blockEnd),
  }
}

// ---------- Model mutations ----------

/**
 * Update a top-level MODEL declaration's fields.
 */
export function updateModel(
  src: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const block = findBlock(src, 'MODEL', null, name)
  if (!block) return src

  const body = serializeFields(fields)
  const newBlock = `MODEL ${formatDslName(name)} {\n${body}\n}\n`
  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

/**
 * Add a new top-level MODEL declaration.
 */
export function addModel(
  src: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const body = serializeFields(fields)
  const newBlock = `MODEL ${formatDslName(name)} {\n${body}\n}\n`

  const modelPattern = /^MODEL\s+(?:"[^"]+"|\S+)\s*\{/gm
  let lastMatch: RegExpExecArray | null = null
  let m: RegExpExecArray | null
  while ((m = modelPattern.exec(src)) !== null) {
    lastMatch = m
  }

  if (lastMatch) {
    const lastBlock = findBlockFromIndex(src, lastMatch.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  const signalPattern = /^SIGNAL\s+\S+\s+\S+\s*\{/gm
  let lastSignal: RegExpExecArray | null = null
  while ((m = signalPattern.exec(src)) !== null) {
    lastSignal = m
  }
  if (lastSignal) {
    const lastBlock = findBlockFromIndex(src, lastSignal.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  const firstNonCommentLine = findFirstNonCommentLine(src)
  return src.slice(0, firstNonCommentLine) + newBlock + '\n' + src.slice(firstNonCommentLine)
}

/**
 * Delete a top-level MODEL declaration.
 */
export function deleteModel(src: string, name: string): string {
  const block = findBlock(src, 'MODEL', null, name)
  if (!block) return src

  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

// ---------- Signal mutations ----------

/**
 * Serialize a signal's fields to DSL block body text.
 * Supports recursive indentation to match Go decompiler output format.
 */
export function serializeFields(fields: DSLFieldObject, indent = '  ', opts?: { blankLineBefore?: boolean }): string {
  const lines: string[] = []
  const entries = Object.entries(fields).filter(([, v]) => v !== undefined && v !== null) as Array<[string, DSLFieldValue]>
  for (const [key, value] of entries) {
    const serialized = serializeValue(value, indent)
    // Add blank line before nested object blocks (matches Go decompiler)
    if (opts?.blankLineBefore && typeof value === 'object' && !Array.isArray(value) && value !== null) {
      lines.push('')
    }
    lines.push(`${indent}${key}: ${serialized}`)
  }
  return lines.join('\n')
}

/**
 * Count the number of leaf (non-object) fields in an object, recursively.
 */
function countLeafFields(obj: DSLFieldObject): number {
  let count = 0
  for (const v of Object.values(obj)) {
    if (v === undefined || v === null) continue
    if (isDSLFieldObject(v)) {
      count += countLeafFields(v)
    } else {
      count++
    }
  }
  return count
}

function serializeValue(value: DSLFieldValue, currentIndent = '  '): string {
  if (typeof value === 'string') return `"${value}"`
  if (typeof value === 'number') return String(value)
  if (typeof value === 'boolean') return value ? 'true' : 'false'
  if (value === null) return 'null'
  if (Array.isArray(value)) {
    if (value.length === 0) return '[]'
    const simple = value.every(v => typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean')
    if (simple) {
      return `[${value.map(v => serializeValue(v, currentIndent)).join(', ')}]`
    }
    const childIndent = currentIndent + '  '
    const items = value.map(v => `${childIndent}${serializeValue(v, childIndent)}`).join(',\n')
    return `[\n${items}\n${currentIndent}]`
  }
  if (isDSLFieldObject(value)) {
    const entries = Object.entries(value).filter(([, v]) => v !== undefined && v !== null) as Array<[string, DSLFieldValue]>
    if (entries.length === 0) return '{}'
    // Inline small flat objects (≤3 leaf fields, all primitive) — matches Go decompiler style
    const leafCount = countLeafFields(value)
    const allPrimitive = entries.every(([, v]) => typeof v !== 'object' || v === null)
    if (allPrimitive && leafCount <= 3) {
      const parts = entries.map(([k, v]) => `${k}: ${serializeValue(v, currentIndent)}`)
      return `{ ${parts.join(', ')} }`
    }
    // Multi-line nested object
    const childIndent = currentIndent + '  '
    const inner = serializeFields(value, childIndent)
    if (!inner.trim()) return '{}'
    return `{\n${inner}\n${currentIndent}}`
  }
  return String(value)
}

/**
 * Update a signal's fields in DSL source.
 * Replaces the entire block body with new field values.
 */
export function updateSignal(
  src: string,
  signalType: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const block = findBlock(src, 'SIGNAL', signalType, name)
  if (!block) return src

  const body = serializeFields(fields)
  const newBlock = `SIGNAL ${signalType} ${name} {\n${body}\n}\n`

  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

/**
 * Add a new signal to the DSL source.
 * Inserts after the last existing SIGNAL block, or at the top if none exist.
 */
export function addSignal(
  src: string,
  signalType: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const body = serializeFields(fields)
  const newBlock = `SIGNAL ${signalType} ${name} {\n${body}\n}\n`

  // Find last SIGNAL block
  const signalPattern = /^SIGNAL\s+\S+\s+\S+\s*\{/gm
  let lastMatch: RegExpExecArray | null = null
  let m: RegExpExecArray | null
  while ((m = signalPattern.exec(src)) !== null) {
    lastMatch = m
  }

  if (lastMatch) {
    // Find the end of the last signal block
    const lastBlock = findBlockFromIndex(src, lastMatch.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  // No existing signals — insert at top (after any comments)
  const firstNonCommentLine = findFirstNonCommentLine(src)
  return src.slice(0, firstNonCommentLine) + newBlock + '\n' + src.slice(firstNonCommentLine)
}

/**
 * Delete a signal from the DSL source.
 */
export function deleteSignal(src: string, signalType: string, name: string): string {
  const block = findBlock(src, 'SIGNAL', signalType, name)
  if (!block) return src

  // Remove extra blank lines left behind
  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

function buildNamedBlock(
  header: string,
  fields: DSLFieldObject,
): string {
  const body = serializeFields(fields)
  return `${header} {\n${body}\n}\n`
}

function insertAfterLastBlock(
  src: string,
  patterns: RegExp[],
  newBlock: string,
): string {
  for (const pattern of patterns) {
    let lastMatch: RegExpExecArray | null = null
    let match: RegExpExecArray | null
    while ((match = pattern.exec(src)) !== null) {
      lastMatch = match
    }
    if (!lastMatch) {
      continue
    }
    const lastBlock = findBlockFromIndex(src, lastMatch.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  const firstNonCommentLine = findFirstNonCommentLine(src)
  return src.slice(0, firstNonCommentLine) + newBlock + '\n' + src.slice(firstNonCommentLine)
}

export function updateProjectionPartition(
  src: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const block = findBlock(src, 'PROJECTION', 'partition', name)
  if (!block) return src
  const newBlock = buildNamedBlock(`PROJECTION partition ${formatDslName(name)}`, fields)
  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

export function addProjectionPartition(
  src: string,
  name: string,
  fields: DSLFieldObject,
): string {
  const newBlock = buildNamedBlock(`PROJECTION partition ${formatDslName(name)}`, fields)
  return insertAfterLastBlock(src, [
    /^PROJECTION\s+\S+\s+(?:"[^"]+"|\S+)\s*\{/gm,
    /^SIGNAL\s+\S+\s+(?:"[^"]+"|\S+)\s*\{/gm,
  ], newBlock)
}

export function deleteProjectionPartition(src: string, name: string): string {
  const block = findBlock(src, 'PROJECTION', 'partition', name)
  if (!block) return src
  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

export function updateProjection(
  src: string,
  kind: 'partition' | 'score' | 'mapping',
  name: string,
  fields: DSLFieldObject,
): string {
  const block = findBlock(src, 'PROJECTION', kind, name)
  if (!block) return src
  const newBlock = buildNamedBlock(`PROJECTION ${kind} ${formatDslName(name)}`, fields)
  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

export function addProjection(
  src: string,
  kind: 'partition' | 'score' | 'mapping',
  name: string,
  fields: DSLFieldObject,
): string {
  const newBlock = buildNamedBlock(`PROJECTION ${kind} ${formatDslName(name)}`, fields)
  return insertAfterLastBlock(src, [
    /^PROJECTION\s+\S+\s+(?:"[^"]+"|\S+)\s*\{/gm,
    /^SIGNAL\s+\S+\s+(?:"[^"]+"|\S+)\s*\{/gm,
  ], newBlock)
}

export function deleteProjection(
  src: string,
  kind: 'partition' | 'score' | 'mapping',
  name: string,
): string {
  const block = findBlock(src, 'PROJECTION', kind, name)
  if (!block) return src
  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

/**
 * Update a plugin declaration's fields.
 */
export function updatePlugin(
  src: string,
  name: string,
  pluginType: string,
  fields: DSLFieldObject,
): string {
  const block = findBlock(src, 'PLUGIN', pluginType, name)
  if (!block) return src

  const body = serializeFields(fields)
  const newBlock = `PLUGIN ${name} ${pluginType} {\n${body}\n}\n`
  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

/**
 * Add a new plugin declaration.
 */
export function addPlugin(
  src: string,
  name: string,
  pluginType: string,
  fields: DSLFieldObject,
): string {
  const body = serializeFields(fields)
  const newBlock = `PLUGIN ${name} ${pluginType} {\n${body}\n}\n`

  // Find insertion point — after last PLUGIN or after last SIGNAL
  const pluginPattern = /^PLUGIN\s+\S+\s+\S+\s*\{/gm
  let lastMatch: RegExpExecArray | null = null
  let m: RegExpExecArray | null
  while ((m = pluginPattern.exec(src)) !== null) {
    lastMatch = m
  }

  if (lastMatch) {
    const lastBlock = findBlockFromIndex(src, lastMatch.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  // No plugins — insert after signals
  const signalPattern2 = /^SIGNAL\s+\S+\s+\S+\s*\{/gm
  let lastSig: RegExpExecArray | null = null
  while ((m = signalPattern2.exec(src)) !== null) {
    lastSig = m
  }
  if (lastSig) {
    const lastBlock = findBlockFromIndex(src, lastSig.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  return src + '\n' + newBlock
}

/**
 * Delete a plugin declaration.
 */
export function deletePlugin(src: string, name: string, pluginType: string): string {
  const block = findBlock(src, 'PLUGIN', pluginType, name)
  if (!block) return src
  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

/**
 * Delete a route declaration.
 */
export function deleteRoute(src: string, name: string): string {
  const block = findBlock(src, 'ROUTE', null, name)
  if (!block) return src
  let result = src.slice(0, block.start) + src.slice(block.end)
  result = result.replace(/\n{3,}/g, '\n\n')
  return result
}

// ---------- Route mutations ----------

export interface RouteModelInput {
  model: string
  reasoning?: boolean
  effort?: string
  lora?: string
  paramSize?: string
  weight?: number
  reasoningFamily?: string
}

export interface RouteAlgoInput {
  algoType: string
  fields: DSLFieldObject
}

export interface RoutePluginInput {
  name: string
  fields?: DSLFieldObject
}

export interface RouteInput {
  description?: string
  priority: number
  when?: string            // raw WHEN expression text, e.g. "domain(\"math\") AND complexity(\"hard\")"
  models: RouteModelInput[]
  algorithm?: RouteAlgoInput
  plugins: RoutePluginInput[]
}

function serializeRouteBody(input: RouteInput): string {
  const lines: string[] = []

  // Priority
  lines.push(`  PRIORITY ${input.priority}`)
  lines.push('')

  // WHEN
  if (input.when && input.when.trim()) {
    lines.push(`  WHEN ${input.when.trim()}`)
    lines.push('')
  }

  // Models
  if (input.models.length > 0) {
    const modelParts = input.models.map((m) => {
      const attrs: string[] = []
      if (m.reasoning !== undefined) attrs.push(`reasoning = ${m.reasoning}`)
      if (m.effort) attrs.push(`effort = "${m.effort}"`)
      if (m.lora) attrs.push(`lora = "${m.lora}"`)
      if (m.paramSize) attrs.push(`param_size = "${m.paramSize}"`)
      if (m.weight !== undefined) attrs.push(`weight = ${m.weight}`)
      if (m.reasoningFamily) attrs.push(`reasoning_family = "${m.reasoningFamily}"`)
      const attrStr = attrs.length > 0 ? ` (${attrs.join(', ')})` : ''
      return `"${m.model}"${attrStr}`
    })
    if (modelParts.length === 1) {
      lines.push(`  MODEL ${modelParts[0]}`)
    } else {
      lines.push(`  MODEL ${modelParts.join(',\n        ')}`)
    }
    lines.push('')
  }

  // Algorithm
  if (input.algorithm && input.algorithm.algoType) {
    const algoFields = serializeFields(input.algorithm.fields, '    ')
    if (algoFields.trim()) {
      lines.push(`  ALGORITHM ${input.algorithm.algoType} {`)
      lines.push(algoFields)
      lines.push(`  }`)
    } else {
      lines.push(`  ALGORITHM ${input.algorithm.algoType} {}`)
    }
    lines.push('')
  }

  // Plugins
  for (const p of input.plugins) {
    if (p.fields && Object.keys(p.fields).length > 0) {
      const pluginFields = serializeFields(p.fields, '    ')
      lines.push(`  PLUGIN ${p.name} {`)
      lines.push(pluginFields)
      lines.push(`  }`)
    } else {
      lines.push(`  PLUGIN ${p.name}`)
    }
  }

  return lines.join('\n')
}

/**
 * Update a route's content in DSL source.
 */
export function updateRoute(
  src: string,
  name: string,
  input: RouteInput,
): string {
  const block = findBlock(src, 'ROUTE', null, name)
  if (!block) return src

  const descPart = input.description ? ` (description = "${input.description}")` : ''
  const body = serializeRouteBody(input)
  const newBlock = `ROUTE ${name}${descPart} {\n${body}\n}\n`
  return src.slice(0, block.start) + newBlock + src.slice(block.end)
}

/**
 * Add a new route to the DSL source.
 * Inserts after the last existing ROUTE block, or after signals if none exist.
 */
export function addRoute(
  src: string,
  name: string,
  input: RouteInput,
): string {
  const descPart = input.description ? ` (description = "${input.description}")` : ''
  const body = serializeRouteBody(input)
  const newBlock = `ROUTE ${name}${descPart} {\n${body}\n}\n`

  // Find last ROUTE block
  const routePattern = /^ROUTE\s+\S+/gm
  let lastMatch: RegExpExecArray | null = null
  let m: RegExpExecArray | null
  while ((m = routePattern.exec(src)) !== null) {
    lastMatch = m
  }

  if (lastMatch) {
    const lastBlock = findBlockFromIndex(src, lastMatch.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  // No routes — insert after signals
  const signalPattern2 = /^SIGNAL\s+\S+\s+\S+\s*\{/gm
  let lastSig: RegExpExecArray | null = null
  while ((m = signalPattern2.exec(src)) !== null) {
    lastSig = m
  }
  if (lastSig) {
    const lastBlock = findBlockFromIndex(src, lastSig.index)
    if (lastBlock) {
      return src.slice(0, lastBlock.end) + '\n' + newBlock + src.slice(lastBlock.end)
    }
  }

  return src + '\n' + newBlock
}

/**
 * Serialize a BoolExprNode back to DSL text.
 */
export function serializeBoolExpr(expr: BoolExprNode | null): string {
  if (!expr) return ''
  const type = expr.type
  switch (type) {
    case 'signal_ref':
      return `${expr.signalType}("${expr.signalName}")`
    case 'and':
      return `${serializeBoolExpr(expr.left)} AND ${serializeBoolExpr(expr.right)}`
    case 'or':
      return `(${serializeBoolExpr(expr.left)} OR ${serializeBoolExpr(expr.right)})`
    case 'not':
      return `NOT ${serializeBoolExpr(expr.expr)}`
    default:
      return ''
  }
}

function isDSLFieldObject(value: DSLFieldValue): value is DSLFieldObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

/**
 * Rename an entity (signal, plugin, backend).
 * Finds the block and replaces the old name with the new name in the header.
 */
export function renameSignal(
  src: string,
  signalType: string,
  oldName: string,
  newName: string,
): string {
  const block = findBlock(src, 'SIGNAL', signalType, oldName)
  if (!block) return src

  const newHeader = block.body.replace(
    new RegExp(`^SIGNAL\\s+${escRe(signalType)}\\s+${escRe(oldName)}`),
    `SIGNAL ${signalType} ${newName}`,
  )
  return src.slice(0, block.start) + newHeader + src.slice(block.end)
}

// ---------- Helpers ----------

function escRe(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

function dslNamePattern(name: string): string {
  return `(?:${escRe(name)}|"${escRe(name)}")`
}

function formatDslName(name: string): string {
  return /^[_A-Za-z][\w]*$/.test(name) ? name : `"${name}"`
}

function findBlockFromIndex(src: string, startIndex: number): BlockSpan | null {
  let braceCount = 0
  let blockEnd = startIndex
  let foundOpenBrace = false

  for (let i = startIndex; i < src.length; i++) {
    if (src[i] === '{') {
      braceCount++
      foundOpenBrace = true
    } else if (src[i] === '}') {
      braceCount--
      if (foundOpenBrace && braceCount === 0) {
        blockEnd = i + 1
        while (blockEnd < src.length && (src[blockEnd] === '\n' || src[blockEnd] === '\r')) {
          blockEnd++
        }
        return { start: startIndex, end: blockEnd, body: src.slice(startIndex, blockEnd) }
      }
    }
  }
  return null
}

function findFirstNonCommentLine(src: string): number {
  const lines = src.split('\n')
  let offset = 0
  for (const line of lines) {
    const trimmed = line.trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      offset += line.length + 1
    } else {
      break
    }
  }
  return offset
}

