91	// compile implements signalCompile(dslSource: string) → string (JSON).
92	// Full pipeline: DSL → parse → validate → compile → emit YAML + CRD.
93	func compile(_ js.Value, args []js.Value) interface{} {
94		if len(args) < 1 {
95			return marshalJSON(CompileResult{Error: "signalCompile requires 1 argument: dslSource"})
96		}
97		dslSource := args[0].String()
98	
99		// 1. Parse → AST (for Visual Builder consumption).
100		prog, parseErrs := dsl.Parse(dslSource)
101		var astJSON interface{}
102		if prog != nil {
103			astJSON = dsl.ProgramToJSON(prog)
104		}
105	
106		// 2. Validate (includes lex + parse + reference + constraint checks).
107		diags, valErrs := dsl.Validate(dslSource)
108		diagnostics := convertDiagnostics(diags)
109		diagnostics = appendRuntimeValidationWarning(diagnostics, prog)
110	
111		// 3. Compile DSL → RouterConfig.
112		cfg, compileErrs := dsl.Compile(dslSource)
113		if len(compileErrs) > 0 {
114			_ = parseErrs // already captured in diagnostics
115			// Still return diagnostics and partial AST even on compile errors.
116			return marshalJSON(CompileResult{
117				AST:         astJSON,
118				Diagnostics: diagnostics,
119				Error:       joinErrors(compileErrs),
120			})
121		}
122	
123		// 3. Emit the canonical routing fragment owned by the DSL surface.
124		yamlBytes, yamlErr := dsl.EmitRoutingYAMLFromConfig(cfg)
125		if yamlErr != nil {
126			return marshalJSON(CompileResult{
127				Diagnostics: diagnostics,
128				Error:       yamlErr.Error(),
129			})
130		}
131	
132		// 4. Emit CRD (with default name/namespace).
133		crdBytes, crdErr := dsl.EmitCRD(cfg, "router", "default")
134		crdStr := ""
135		if crdErr == nil {
136			crdStr = string(crdBytes)
137		}
138	
139		// If there were validation parse errors, include them but still return output.
140		errStr := ""
141		if len(valErrs) > 0 {
142			errStr = joinErrors(valErrs)
143		}
144	
145		return marshalJSON(CompileResult{
146			YAML:        string(yamlBytes),
147			CRD:         crdStr,
148			Diagnostics: diagnostics,
149			AST:         astJSON,
150			Error:       errStr,
151		})
152	}
