154	// validate implements signalValidate(dslSource: string) → string (JSON).
155	// Incremental validation only — faster than full compile.
156	// Also returns the symbol table extracted from the AST for editor completions.
157	func validate(_ js.Value, args []js.Value) interface{} {
158		if len(args) < 1 {
159			return marshalJSON(ValidateResult{Error: "signalValidate requires 1 argument: dslSource"})
160		}
161		dslSource := args[0].String()
162	
163		prog, _ := dsl.Parse(dslSource)
164		diags, symbols, valErrs := dsl.ValidateWithSymbols(dslSource)
165		diagnostics := convertDiagnostics(diags)
166		diagnostics = appendRuntimeValidationWarning(diagnostics, prog)
167	
168		errorCount := 0
169		for _, d := range diags {
170			if d.Level == dsl.DiagError {
171				errorCount++
172			}
173		}
174	
175		errStr := ""
176		if len(valErrs) > 0 {
177			errStr = joinErrors(valErrs)
178		}
