42	
43	interface VisualModeProps {
44	  ast: ReturnType<typeof useDSLStore.getState>["ast"];
45	  dslSource: string;
46	  diagnostics: Diagnostic[];
47	  selection: Selection | null;
48	  onSelect: (sel: Selection | null) => void;
49	  sections: SectionState;
50	  onToggleSection: (key: keyof SectionState) => void;
51	  selectedEntity: BuilderSelectedEntity;
52	  modelCount: number;
53	  signalCount: number;
54	  projectionPartitionCount: number;
55	  projectionScoreCount: number;
56	  projectionMappingCount: number;
57	  routeCount: number;
58	  pluginCount: number;
59	  wasmReady: boolean;
60	  wasmError: string | null;
61	  addingEntity: EntityKind | null;
62	  onSetAddingEntity: (kind: EntityKind | null) => void;
63	  onDeleteEntity: (kind: EntityKind, name: string, subType?: string) => void;
64	  onUpdateModelFields: (name: string, fields: DSLFieldObject) => void;
65	  onUpdateSignalFields: (
66	    signalType: string,
67	    name: string,
68	    fields: DSLFieldObject,
69	  ) => void;
70	  onUpdateProjectionPartitionFields: (name: string, fields: DSLFieldObject) => void;
71	  onUpdateProjectionScoreFields: (
72	    name: string,
73	    fields: DSLFieldObject,
74	  ) => void;
75	  onUpdateProjectionMappingFields: (
76	    name: string,
77	    fields: DSLFieldObject,
78	  ) => void;
79	  onUpdatePluginFields: (
80	    name: string,
81	    pluginType: string,
82	    fields: DSLFieldObject,
