102	  onModeSwitch: (mode: EditorMode) => void;
103	}
104	
105	const VisualMode: React.FC<VisualModeProps> = ({
106	  ast,
107	  diagnostics,
108	  selection,
109	  onSelect,
110	  sections,
111	  onToggleSection,
112	  selectedEntity,
113	  modelCount,
114	  signalCount,
115	  projectionPartitionCount,
116	  projectionScoreCount,
117	  projectionMappingCount,
118	  routeCount,
119	  pluginCount,
120	  wasmReady,
121	  wasmError,
122	  addingEntity,
123	  onSetAddingEntity,
124	  onDeleteEntity,
125	  onUpdateModelFields,
126	  onUpdateSignalFields,
127	  onUpdateProjectionPartitionFields,
128	  onUpdateProjectionScoreFields,
129	  onUpdateProjectionMappingFields,
130	  onUpdatePluginFields,
131	  onAddModel,
132	  onAddSignal,
133	  onAddProjectionPartition,
134	  onAddProjectionScore,
135	  onAddProjectionMapping,
136	  onAddPlugin,
137	  onUpdateRoute,
138	  onAddRoute,
139	  errorCount,
140	  isValid,
141	  onModeSwitch,
142	}) => {
143	  // Collect available signal names for expression builder
144	  // Complexity signals are referenced as "<name>:easy", "<name>:medium", "<name>:hard" in route conditions
145	  const availableSignals = useMemo(() => {
146	    const result: { signalType: string; name: string }[] = [];
147	    for (const s of ast?.signals ?? []) {
148	      if (s.signalType === "complexity") {
149	        result.push({ signalType: s.signalType, name: `${s.name}:easy` });
150	        result.push({ signalType: s.signalType, name: `${s.name}:medium` });
151	        result.push({ signalType: s.signalType, name: `${s.name}:hard` });
152	      } else {
153	        result.push({ signalType: s.signalType, name: s.name });
154	      }
155	    }
156	    for (const mapping of ast?.projectionMappings ?? []) {
157	      for (const output of mapping.outputs ?? []) {
158	        result.push({ signalType: "projection", name: output.name });
159	      }
160	    }
161	    return result;
162	  }, [ast?.signals, ast?.projectionMappings]);
163	  // Collect available plugin names for toggle panel
164	  const availablePlugins = useMemo(
165	    () =>
166	      ast?.plugins?.map((p) => ({ name: p.name, pluginType: p.pluginType })) ??
167	      [],
168	    [ast?.plugins],
169	  );
170	  const semanticModels = useMemo(
171	    () => ast?.models?.map((model) => model.name) ?? [],
172	    [ast?.models],
173	  );
174	  // Collect available model names for route selection.
175	  const availableModels = useMemo(() => {
176	    if (semanticModels.length > 0) {
177	      return [...semanticModels].sort()
178	    }
179	    const modelSet = new Set<string>();
180	    ast?.routes?.forEach((r) =>
181	      r.models.forEach((m) => {
182	        if (m.model) modelSet.add(m.model);
183	      }),
184	    );
185	    return Array.from(modelSet).sort();
186	  }, [ast?.routes, semanticModels]);
187	
188	  // Validation panel state
189	  const [validationOpen, setValidationOpen] = useState(true);
190	  const errorDiags = useMemo(
191	    () => diagnostics.filter((d) => d.level === "error"),
192	    [diagnostics],
193	  );
194	  const warnDiags = useMemo(
195	    () => diagnostics.filter((d) => d.level === "warning"),
196	    [diagnostics],
197	  );
198	  const constraintDiags = useMemo(
199	    () => diagnostics.filter((d) => d.level === "constraint"),
200	    [diagnostics],
201	  );
202	
203	  const handleApplyFix = useCallback((diag: Diagnostic, newText: string) => {
204	    const store = useDSLStore.getState();
205	    const src = store.dslSource;
206	    const lines = src.split("\n");
207	    if (diag.line < 1 || diag.line > lines.length) return;
208	
209	    const lineContent = lines[diag.line - 1];
210	    let startCol = diag.column;
211	    let endCol = diag.column;
212	    while (startCol > 1 && /[\w\-.]/.test(lineContent[startCol - 2]))
213	      startCol--;
214	    while (
215	      endCol <= lineContent.length &&
216	      /[\w\-.]/.test(lineContent[endCol - 1])
217	    )
218	      endCol++;
219	
220	    const before = lineContent.slice(0, startCol - 1);
221	    const after = lineContent.slice(endCol - 1);
222	    lines[diag.line - 1] = before + newText + after;
223	
224	    const newSrc = lines.join("\n");
225	    useDSLStore.getState().setDslSource(newSrc);
226	    // Re-parse AST for visual mode
227	    if (useDSLStore.getState().wasmReady) useDSLStore.getState().parseAST();
228	  }, []);
229	
230	  return (
231	    <div className={styles.visualContainer}>
232	      <div className={styles.visualRow}>
233	        {/* Sidebar */}
234	        <div className={styles.sidebar}>
235	          {/* Dashboard home link */}
236	          <div
237	            className={
238	              selection === null && !addingEntity
239	                ? styles.sidebarHomeActive
240	                : styles.sidebarHome
241	            }
242	            onClick={() => {
243	              onSetAddingEntity(null);
244	              onSelect(null);
245	            }}
246	          >
247	            <svg
248	              width="14"
249	              height="14"
250	              viewBox="0 0 24 24"
251	              fill="none"
252	              stroke="currentColor"
253	              strokeWidth="2"
254	              strokeLinecap="round"
255	              strokeLinejoin="round"
256	            >
